L9_1 = {}
L9_1.m_CutScenKey_Talk = "EP5_ACT5_STAGE4_START@9#Talk"
L9_1.m_CutScenProcessKey = 9
L9_1.m_CutScenID = 208
L9_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L9_1.m_Pos = "C"
L9_1.m_Talk_KOREA = "그녀는 아직 어려. 주변의 압력을 이겨내고 자기 생각을 솔직하게 말하기엔 조금 이르지."
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "彼女はまだ若い。\n周りの目を気にせず、自分の考えを正直に話すのはまだ早いだろう。"
L9_1.m_Talk_ENG = "She's still young. She's not mature enough to express her honest opinions without being affected by outside pressures."
L9_1.m_Talk_TWN = "她還年輕，要她克服周圍的壓力，坦率說出自己的想法還太早了。"
L9_1.m_Talk_THA = "เธอยังเด็ก เธอยังไม่โตพอที่จะแสดงความเห็นอย่างตรงไปตรงมาโดยไม่ได้รับผลกระทบจากแรงกดดันภายนอกนะ"
L9_1.m_Talk_VTN = "Cô ấy vẫn còn trẻ. Cô ấy chưa đủ trưởng thành để bày tỏ trung thực ý kiến của mình mà không bị ảnh hưởng bởi những áp lực bên ngoài."
L9_1.m_Talk_SCN = "她还小，让她克服周围的压力说出自己的想法还太早了。"
L9_1.m_Talk_DEU = "Sie ist noch jung und nicht in der Lage, zu ihrer eigenen Meinung zu stehen."
L9_1.m_Talk_FRA = "Elle est encore jeune. Elle ne sait pas exprimer ses véritables opinions sans être affectée par des pressions extérieures."
