L12_1.m_Crash = 25
L12_1.m_Talk_KOREA = "다, 당신은?! 그때 그 홀로그램에서 본......!!"
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "あ、あなたは！？　あの時のホログラムに出てた……！！"
L12_1.m_Talk_ENG = "Y-you! I saw you in the hologram!"
L12_1.m_Talk_TWN = "你、你是？！那個時候在全息影像看到的……！！"
L12_1.m_Talk_THA = "คะ-คุณ! ฉันเห็นคุณในโฮโลแกรม!"
L12_1.m_Talk_VTN = "Ông! Tôi đã nhìn thấy bạn trong hình ba chiều!"
L12_1.m_Talk_SCN = "你，你是？！当时在全息图里见过的……！！"
L12_1.m_Talk_DEU = "D-Du! Dich habe ich als Hologramm gesehen!"
L12_1.m_Talk_FRA = "V-Vous ! Je vous ai vu dans l'hologramme !"
