L14_1.m_Talk_KOREA = "실비아 양이 속한 델타세븐의 전 부사령관이었다는......"
L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "シルビアさんがいるデルタセブンの元副司令官だったという……"
L14_1.m_Talk_ENG = "The former deputy commander of Delta Seven, where Sylvia now works."
L14_1.m_Talk_TWN = "希爾維亞小姐所屬的第七三角洲部隊前副司令官……"
L14_1.m_Talk_THA = "อดีตรองผู้บัญชาการของเดลต้าเซเว่น ที่ที่ซิลเวียทำงาน"
L14_1.m_Talk_VTN = "Cựu phó tư lệnh của Delta Seven, nơi Sylvia hiện đang làm việc."
L14_1.m_Talk_SCN = "希尔薇娅小姐所属的德尔塔部队的前副司令官……"
L14_1.m_Talk_DEU = "Der frühere stellvertretende Kommandant von Delta Seven, wo Sylvia jetzt arbeitet."
