L16_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_Face = "UNIT_DESPAIR"
L16_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L16_1.m_Pos = "C"
L16_1.m_Talk_KOREA = "안타깝지만...... 이제는 지나간 옛 이야기지."
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "残念ながら……もう昔の話だ。"
L16_1.m_Talk_ENG = "Ah, they're fond memories, but that was ages ago."
L16_1.m_Talk_TWN = "很遺憾……那都是過去的事情了。"
L16_1.m_Talk_THA = "อา ความทรงจำหวานชื่น แต่มันผ่านมาเป็นชาติแล้วละ"
L16_1.m_Talk_VTN = "Ah, chúng là những kỷ niệm đẹp, nhưng đã lâu lắm rồi."
L16_1.m_Talk_SCN = "很可惜……那都是过去的事情了。"
L16_1.m_Talk_DEU = "Ja, ich erinnere mich gern, aber das ist lange her."
L16_1.m_Talk_FRA = "Ah, que de bons souvenirs, mais ils semblent tellement loin maintenant."
L17_1 = {}
L17_1.m_CutScenKey_Talk = "EP5_ACT5_STAGE4_START@17#Talk"
L17_1.m_CutScenProcessKey = 17
L17_1.m_CutScenID = 208
L17_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_Face = "UNIT_IDLE"
L17_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L17_1.m_Pos = "C"
L17_1.m_Talk_KOREA = "그보다, 뉴 오하이오에 승선한 것을 환영하네."
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "それより、ニューオハイオへの乗船を歓迎しよう。"
L17_1.m_Talk_ENG = "Anyway, welcome aboard the New Ohio."
L17_1.m_Talk_TWN = "歡迎你們登上新俄亥俄。"
L17_1.m_Talk_THA = "แล้วก็ยินดีต้อนรับสู่นิวโอไฮโอ"
L17_1.m_Talk_VTN = "Dù sao cũng chào mừng đã đến Tân Ohio."
L17_1.m_Talk_SCN = "欢迎你们登上伊欧。"
L17_1.m_Talk_DEU = "Doch zunächst einmal: Willkommen auf der New Ohio."
L17_1.m_Talk_FRA = "Quoiqu'il en soit, je vous souhaite la bienvenue dans le New Ohio."
L18_1 = {}
L18_1.m_CutScenKey_Talk = "EP5_ACT5_STAGE4_START@18#Talk"
L18_1.m_CutScenProcessKey = 18
L18_1.m_CutScenID = 208
L18_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L18_1.m_Pos = "C"
L18_1.m_Talk_KOREA = "직접 만나는 건 처음이지만, 자네들의 이름은 그동안 나도 많이 들었지."
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "初対面だが、君たちの名は聞きなれている。"
L18_1.m_Talk_ENG = "It's my first time meeting you, but I've heard your names many times over."
L18_1.m_Talk_TWN = "雖然我們是第一次見面，但你們的名字我很常聽到。"
L18_1.m_Talk_THA = "นี่เป็นครั้งแรกที่ได้พบคุณ แต่ผมได้ยินชื่อคุณมาหลายครั้งแล้ว"
L18_1.m_Talk_VTN = "Đây là lần đầu tiên tôi gặp cô, nhưng tôi đã nghe tên của cô nhiều lần."
L18_1.m_Talk_SCN = "虽然我们是第一次见面，但你们的名字我常听说。"
L18_1.m_Talk_DEU = "Ich habe schon viel von dir gehört."
L18_1.m_Talk_FRA = "C'est la première fois que je vous rencontre, mais j'ai entendu vos noms à de nombreuses reprises."
L19_1 = {}
L19_1.m_CutScenKey_Talk = "EP5_ACT5_STAGE4_START@19#Talk"
L19_1.m_CutScenProcessKey = 19
L19_1.m_CutScenID = 208
L19_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L19_1.m_Pos = "C"
L19_1.m_Talk_KOREA = "우리 간부들이 자네들 덕분에 꽤나 고생했다고 하더군."
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "うちの幹部たちが、君たちのおかげでずいぶん苦労したと言っていたな。"
L19_1.m_Talk_ENG = "My officers say you gave them a hard time."
L19_1.m_Talk_TWN = "聽說我們的幹部因為你們，吃了很多苦頭呢。"
L19_1.m_Talk_THA = "เจ้าหน้าที่ของผมบอกว่าคุณทำให้พวกเขาลำบากน่าดู"
L19_1.m_Talk_VTN = "Các sĩ quan của tôi nói rằng cô đã khiến họ có một khoảng thời gian khó khăn."
L19_1.m_Talk_SCN = "托你们的福，我们的头目们很是辛苦呢。"
L19_1.m_Talk_DEU = "Meine Offiziere sagen, du hast ihnen das Leben schwer gemacht."
L19_1.m_Talk_FRA = "Mes officiers me rapportent que vous leur avez donné du fil à retordre."
