L21_1 = {}
L21_1.m_CutScenKey_Talk = "EP5_ACT5_STAGE4_START@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 208
L21_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_Face = "UNIT_LAUGH"
L21_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L21_1.m_Pos = "C"
L21_1.m_Talk_KOREA = "대단해. 이건 가감 없는 내 진심일세."
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "すごいな。これは私の素直な感想だ。"
L21_1.m_Talk_ENG = "That's impressive. I mean it, I'm truly impressed."
L21_1.m_Talk_TWN = "真厲害，這是我發自內心的話語。"
L21_1.m_Talk_THA = "น่าประทับใจ ผมพูดจริงๆ นะ ผมประทับใจมาก"
L21_1.m_Talk_VTN = "Ấn tượng đấy. Ý tôi là nó, tôi thực sự ấn tượng."
L21_1.m_Talk_SCN = "真厉害，这是我由衷的感慨，发自内心的话。"
L21_1.m_Talk_DEU = "Das ist beeindruckend. Wirklich, ich bin beeindruckt."
L21_1.m_Talk_FRA = "C'est impressionnant. Je le pense, je suis réellement impressionné."
L22_1 = {}
L22_1.m_CutScenKey_Talk = "EP5_ACT5_STAGE4_START@22#Talk"
L22_1.m_CutScenProcessKey = 22
L22_1.m_CutScenID = 208
L22_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L22_1.m_Pos = "C"
L22_1.m_Talk_KOREA = "일을 벌인 내가 할 말은 아니지만, 어린 나이에 험한 사건들을 겪으면서 꽤나 시련이 많았을 것 같은데......"
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "この事態を作った私の言うことではないが、\n若くして散々な目に遭って大変だったと思うが……"
L22_1.m_Talk_ENG = "I'm the one who started all this, so it might be awkward coming from me, but you've experienced so many hardships at such a young age..."
L22_1.m_Talk_TWN = "雖然是我惹的事端，這話不該由我來說，但是妳小小年紀就經歷這麼險惡的事情，恐怕通過很多的試煉吧……"
L22_1.m_Talk_THA = "ผมเป็นคนที่เริ่มต้นเรื่องทั้งหมด การจะให้ผมพูดแบบนี้อาจฟังดูแปลกๆ นะ แต่คุณต้องเจอเรื่องยากๆ ตั้งแต่อายุยังน้อย..."
L22_1.m_Talk_VTN = "Tôi là người đã bắt đầu tất cả những điều này, vì vậy có thể tôi sẽ gặp khó khăn, nhưng cô đã trải qua rất nhiều khó khăn khi còn trẻ..."
L22_1.m_Talk_SCN = "虽然是我惹的事，这话也不该我来说，但是你小小年纪就经历了这么险恶的事情，应该是有很多困难处境吧……"
L22_1.m_Talk_DEU = "Es mag sich aus meinem Mund komisch anhören, wo ich das alles doch erst angefangen habe, aber du hast in deinen jungen Jahren schon so viel mitgemacht …"
L22_1.m_Talk_FRA = "Je suis à l'origine de tout ceci, alors cela va peut-être vous paraître étrange venant de ma part, mais vous avez traversé tant d'épreuves à un si jeune âge..."
L23_1 = {}
L23_1.m_CutScenKey_Talk = "EP5_ACT5_STAGE4_START@23#Talk"
L23_1.m_CutScenProcessKey = 23
L23_1.m_CutScenID = 208
L23_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L23_1.m_Pos = "C"
L23_1.m_Talk_KOREA = "결국 그 모든 것들을 극복하고 누구보다 먼저 내 앞에 도달했군."
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "ついにその全てを乗り越え、誰よりも早く私のもとへたどり着いた。"
L23_1.m_Talk_ENG = "And you overcame everything to come stand in front of me before anyone else did."
L23_1.m_Talk_TWN = "但是妳最終還是克服了這一切，比誰都還要先來到我的面前。"
L23_1.m_Talk_THA = "และคุณก็เอาชนะทุกอย่างได้ จนมายืนอยู่ข้างหน้าผมได้ก่อนใคร"
L23_1.m_Talk_VTN = "Và cô đã vượt qua mọi thứ để đứng trước mặt tôi trước bất kỳ ai khác."
L23_1.m_Talk_SCN = "但是你最终克服了这种种，第一个到了我的面前啊。"
L23_1.m_Talk_DEU = "Und du hast das alles überstanden und stehst nun lange vor allen anderen vor mir."
L23_1.m_Talk_FRA = "Et vous les avez toutes surmontées pour finalement vous tenir face à moi, avant tout le monde."
L24_1 = {}
L24_1.m_CutScenKey_Talk = "EP5_ACT5_STAGE4_START@24#Talk"
L24_1.m_CutScenProcessKey = 24
L24_1.m_CutScenID = 208
L24_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L24_1.m_Pos = "C"
L24_1.m_Talk_KOREA = "자네들은 내 환영을 받을 만한 가치가 있어. 다시 한 번 환영하네."
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "君たちには私の歓迎を受ける資格がある。改めて、歓迎する。"
L24_1.m_Talk_ENG = "You both deserve my warm welcome. Again, welcome aboard."
L24_1.m_Talk_TWN = "妳值得接受我的歡迎。我要在這裡再次歡迎妳。"
L24_1.m_Talk_THA = "พวกคุณทั้งคู่สมควรได้รับการต้อนรับอย่างอบอุ่น ยินดีต้อนรับ"
L24_1.m_Talk_VTN = "Cả hai người đều xứng đáng được đón tiếp nồng nhiệt của tôi. Một lần nữa, chào mừng lên tàu."
L24_1.m_Talk_SCN = "你们值得接受我的欢迎。再次欢迎你们搭乘伊欧。"
L24_1.m_Talk_DEU = "Du hast dir einen herzlichen Empfang verdient. Also nochmals: Willkommen an Bord."
L24_1.m_Talk_FRA = "Vous méritez tous deux mon accueil le plus chaleureux. Encore une fois, bienvenue à bord."
L25_1 = {}
L25_1.m_CutScenKey_Talk = "EP5_ACT5_STAGE4_START@25#Talk"
