L25_1.m_Talk_KOREA = "집어치워!"
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "いい加減にして！"
L25_1.m_Talk_ENG = "You're crazy!"
L25_1.m_Talk_TWN = "夠了！"
L25_1.m_Talk_THA = "คุณบ้าไปแล้ว!"
L25_1.m_Talk_VTN = "Ông điên rồi!"
L26_1 = "打住！"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Du bist verrückt!"
L25_1.m_Talk_DEU = L26_1
L26_1 = "Vous êtes barge !"
L25_1.m_Talk_FRA = L26_1
