L27_1 = 40
L26_1.m_Crash = L27_1
L27_1 = "고생했다고? 환영한다고? 그게 다 무슨 개소리야?!"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "大変だった？　歓迎する？　冗談じゃないよ！？"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Hardships? A warm welcome? Are you trying to be funny now?"
L26_1.m_Talk_ENG = L27_1
L27_1 = "辛苦？歡迎我們？你說這什麼鬼話啊？！"
L26_1.m_Talk_TWN = L27_1
L27_1 = "เรื่องยากๆ เหรอ? ต้อนรับอย่างอบอุ่นเหรอ? นี่พยายามเล่นตลกอยู่รึไง?"
L26_1.m_Talk_THA = L27_1
L27_1 = "Khó khăn? Chào đón nồng nhiệt? Giờ ông đang cố tỏ ra hài hước sao?"
L26_1.m_Talk_VTN = L27_1
L27_1 = "辛苦了？还欢迎我们？你说的什么鬼话啊？！"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Viel mitgemacht? Herzlicher Empfang? Soll das ein Witz sein?"
L26_1.m_Talk_DEU = L27_1
L27_1 = "Des épreuves ? Un accueil chaleureux ? C'est une blague ?"
L26_1.m_Talk_FRA = L27_1
