L28_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L29_1 = "그동안 우리가 당신과 술래잡기라도 하고 있었던 것 같아?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "これまで私たちと、鬼ごっこでもしてきたつもり？"
L28_1.m_Talk_JPN = L29_1
L29_1 = "You talk like we've been playing hide and seek with you."
L28_1.m_Talk_ENG = L29_1
L29_1 = "你以為我們這段時間在和你玩捉迷藏嗎？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "คุณพูดเหมือนเราเล่นซ่อนแอบกับคุณงั้นแหละ"
L28_1.m_Talk_THA = L29_1
L29_1 = "Ông nói như thể chúng tôi đang chơi trốn tìm với Ông."
L28_1.m_Talk_VTN = L29_1
L29_1 = "那段时间我们好像还和你玩过捉迷藏呢吧？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Du redest ja geradezu, als hätten wir nur Verstecken gespielt."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Vous parlez comme si on venait de jouer à cache-cache avec vous."
L28_1.m_Talk_FRA = L29_1
