L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L31_1 = "당신이 무슨 짓을 했는지는 알고 있어?"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "あんたが何をしでかしたか、わかってるの？"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Are you aware of what you've been doing all this time?"
L30_1.m_Talk_ENG = L31_1
L31_1 = "你知道你做了什麼事情嗎？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "รู้ไหมว่าตัวเองทำอะไรลงไปตลอดเวลาที่ผ่านมา?"
L30_1.m_Talk_THA = L31_1
L31_1 = "Ông có biết mình đã làm gì trong suốt thời gian qua không?"
L30_1.m_Talk_VTN = L31_1
L31_1 = "你做过什么事情你知道吗？"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Ist dir klar, was du da tust?"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Vous vous rendez compte de ce que vous avez fait pendant tout ce temps ?"
L30_1.m_Talk_FRA = L31_1
