L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 32
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 208
L32_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L33_1 = "당신 때문에 고통 받은 사람들이 대체 얼마나 되는지 아느냐고!!"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "あんたのせいで苦しんでる人の数を、知ってるのかって聞いてんの！！"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Do you know how many people had to suffer because of you?"
L32_1.m_Talk_ENG = L33_1
L33_1 = "你知不知道因為你，有多少人陷入痛苦之中啊！"
L32_1.m_Talk_TWN = L33_1
L33_1 = "รู้ไหมว่ามีกี่คนที่ต้องทุกข์ทรมานเพราะคุณ?"
L32_1.m_Talk_THA = L33_1
L33_1 = "Ông có biết bao nhiêu người đã phải khổ sở vì Ông không?"
L32_1.m_Talk_VTN = L33_1
L33_1 = "你知不知道有多少人因为你陷入痛苦之中啊！"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Ist dir klar, wie viele Menschen wegen dir leiden?"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Vous avez conscience du nombre de gens qui souffrent à cause de vous ?"
L32_1.m_Talk_FRA = L33_1
