L34_1.m_Face = "UNIT_SERIOUS2"
L35_1 = "CUTSCENE_AMBIENT_WIND"
L34_1.m_StartBGMFileName = L35_1
L34_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L34_1.m_Pos = "C"
L34_1.m_Crash = 20
L35_1 = "그런데 고작 하는 소리가...... 그거야?"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "他に言うこと……あるんじゃないの？"
L34_1.m_Talk_JPN = L35_1
L35_1 = "And that's what you have to say after all you've done?"
L34_1.m_Talk_ENG = L35_1
L35_1 = "結果你想說的……就這樣？"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ทำเรื่องทั้งหมดนี้แล้วยังกล้าพูดแบบนั้นอีกเหรอ?"
L34_1.m_Talk_THA = L35_1
L35_1 = "Và đó là những gì Ông nói sau tất cả những gì Ông đã làm?"
L34_1.m_Talk_VTN = L35_1
L35_1 = "你就是想说……这个？"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Und mehr fällt dir nicht dazu ein?"
L34_1.m_Talk_DEU = L35_1
L35_1 = "Et c'est tout ce que vous trouvez à dire, après tout ce que vous avez fait ?"
L34_1.m_Talk_FRA = L35_1
