L37_1 = "EP5_ACT5_STAGE4_START@36#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 36
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 208
L36_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_Face = "UNIT_IDLE"
L36_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L36_1.m_Pos = "C"
L37_1 = "<color=#ffd34c>의도치 않게</color> 따위의 말로 자네들을 기만하지는 않겠네."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "<color=#ffd34c>不本意ながら</color>なんて言葉で、君たちのことを欺くつもりはない。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "I won't insult you by saying <color=#ffd34c>I didn't mean it</color>."
L36_1.m_Talk_ENG = L37_1
L37_1 = "我不想用<color=#ffd34c>不是故意</color>之類的話欺騙你們。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ผมจะไม่ดูถูกคุณโดยการบอกว่า<color=#ffd34c>ผมไม่ได้ตั้งใจ</color>นะ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Tôi sẽ không xúc phạm bằng cách nói <color=#ffd34c>tôi không cố ý</color>."
L36_1.m_Talk_VTN = L37_1
L37_1 = "我不想用<color=#ffd34c>无意之举</color>之类的话欺骗你们。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Ich werde dich nicht beleidigen, indem ich sage, <color=#ffd34c>ich wollte das alles nicht</color>."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Je ne vous ferai pas l'affront de dire que <color=#ffd34c>ça n'était pas mon intention</color>."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "EP5_ACT5_STAGE4_START@37#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 37
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 208
L37_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L37_1.m_Pos = "C"
L38_1 = "자네들이 받은 고통에 대해서는 정말로 유감이지만...... 난 나의 행동을 후회하거나 번복할 생각은 없어."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "君たちの辛い経験については、実に残念に思うが……\n私は自分の行動を悔いたり、考えを改めるつもりはない。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "I'm truly sorry for all the pain that you had to suffer, but by no means do I regret my past actions."
L37_1.m_Talk_ENG = L38_1
L38_1 = "對於你們的痛苦，我感到很遺憾……但我不後悔，也不會顛覆我的作為。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ผมเสียใจจริงๆ ที่คุณต้องเจ็บปวด แต่ผมก็ไม่เสียใจในสิ่งที่ผมทำลงไปเลย"
L37_1.m_Talk_THA = L38_1
L38_1 = "Tôi thực sự xin lỗi vì những nỗi đau mà cô đã phải gánh chịu, nhưng không có nghĩa là tôi hối hận về những hành động trong quá khứ của mình."
L37_1.m_Talk_VTN = L38_1
L38_1 = "虽然对于你们的痛苦我很抱歉……但我不后悔也不想推翻我做的事。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Es tut mir wirklich leid, dass du so viel zu erleiden hattest, aber ich bereue meine Taten nicht."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Je suis sincèrement désolé pour toutes les souffrances que je vous ai causées, mais en aucun cas je ne regrette mes agissements."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "EP5_ACT5_STAGE4_START@38#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 38
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 208
L38_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_Face = "UNIT_SERIOUS"
L38_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L38_1.m_Pos = "C"
L38_1.m_Crash = 15
L39_1 = "나래를 그런 꼴로 만들고 저런...... 복제품으로 사람을 농락하면서도 후회하지 않는다고?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "ナルミをあんな目に遭わせて、あんな……レプリカで人を翻弄させたのに、悔いはないって？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "You ruined Narae's life, and you mocked her death by creating her clone. And you don't regret it?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "把娜拉變成那個鬼樣子……用克隆把人類玩弄在手中，你都不後悔嗎？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "คุณทำลายชีวิตของนาแร คุณล้อเล่นกับความตายของเธอโดยการสร้างโคลนของเธอขึ้นมา แล้วคุณยังไม่เสียใจอีกเหรอ?"
L38_1.m_Talk_THA = L39_1
L39_1 = "Ông đã hủy hoại cuộc đời của Narae, và bạn chế nhạo cái chết của cô ấy bằng cách tạo ra bản sao của cô ấy. Và bạn không hối tiếc ư?"
L38_1.m_Talk_VTN = L39_1
L39_1 = "你把娜拉变成那个鬼样子……把人类变成供你戏弄的复制品，你都不后悔吗？"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Du hast Naraes Leben ruiniert und sie noch im Tode verhöhnt, als du einen Klon von ihr geschaffen hast. Und das bereust du nicht?"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Vous avez ruiné la vie de Narae, et en créant son clone, vous ne respectez pas non plus sa mort. Et vous ne regrettez rien ?"
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
