L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 40
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 208
L40_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L40_1.m_Pos = "C"
L41_1 = "대체 뭣 때문에 이런 짓을 하는 거야?"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "いったい何のためにこんなことをしてるの？"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Why are you doing this?"
L40_1.m_Talk_ENG = L41_1
L41_1 = "到底是為了什麼，要做出這種事情？"
L40_1.m_Talk_TWN = L41_1
L41_1 = "คุณทำแบบนี้ทำไม?"
L40_1.m_Talk_THA = L41_1
L41_1 = "Tại sao ông làm điều này?"
L40_1.m_Talk_VTN = L41_1
L41_1 = "到底是为什么要做这样的事情啊？"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Warum tust du das?"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Pourquoi vous faites ça ?"
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "EP5_ACT5_STAGE4_START@41#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 41
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 208
L41_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_Face = "UNIT_SERIOUS2"
L41_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L41_1.m_Pos = "C"
L41_1.m_Crash = 50
L42_1 = "말해 봐! 이유라도 있을 거 아냐?!"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "言ってよ！　理由があるんでしょ！？"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Tell me. You must have a reason!"
L41_1.m_Talk_ENG = L42_1
L42_1 = "告訴我！總有個理由吧？！"
L41_1.m_Talk_TWN = L42_1
L42_1 = "บอกฉันสิ คุณต้องมีเหตุผลนะ!"
L41_1.m_Talk_THA = L42_1
L42_1 = "Nói cho tôi nghe. Phải có lý do chứ!"
L41_1.m_Talk_VTN = L42_1
L42_1 = "说说看啊！好歹得有个理由吧？！"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Heraus damit. Es muss doch einen Grund haben!"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Dites-le-moi. Vous avez forcément une raison !"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "EP5_ACT5_STAGE4_START@42#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 42
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 208
L42_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L42_1.m_bWaitClick = true
