L42_1.m_Face = "UNIT_DESPAIR"
L42_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L42_1.m_Pos = "C"
L43_1 = "이유라......"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "理由か……"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Reason..."
L42_1.m_Talk_ENG = L43_1
L43_1 = "理由……"
L42_1.m_Talk_TWN = L43_1
L43_1 = "เหตุผล..."
L42_1.m_Talk_THA = L43_1
L43_1 = "Lý do..."
L42_1.m_Talk_VTN = L43_1
L43_1 = "理由嘛……"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Einen Grund …"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Une raison..."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "EP5_ACT5_STAGE4_START@43#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 43
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 208
L43_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L43_1.m_Pos = "C"
L44_1 = "여러 가지가 있지만 굳이 하나를 꼽자면......"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "色々あるが、あえて一つ挙げるとしたら……"
L43_1.m_Talk_JPN = L44_1
L44_1 = "There are a few, but to pick one..."
L43_1.m_Talk_ENG = L44_1
L44_1 = "有很多，非要舉出一個的話……"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ผมมีหลายเหตุผลนะ แต่ถ้าให้เลือกข้อเดียว..."
L43_1.m_Talk_THA = L44_1
L44_1 = "Có một vài lý do, nhưng để chọn một..."
L43_1.m_Talk_VTN = L44_1
L44_1 = "有好多理由，非要说一个的话……"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Es gibt sogar mehrere, aber wenn es nur einer sein soll …"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Il y en a quelques-unes, mais si je devais en choisir une..."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "EP5_ACT5_STAGE4_START@44#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 44
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 208
L44_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L44_1.m_Pos = "C"
L45_1 = "그래, 우주가 너무 넓기 때문이라고 하면 어떨까?"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "そうだな、宇宙が広すぎるから、というのはどうだ？"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Yes, how about I do it because the universe is too vast?"
L44_1.m_Talk_ENG = L45_1
L45_1 = "好吧，那說因為宇宙太寬廣了怎麼樣？"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ถ้าผมบอกว่าผมทำเพราะจักรวาลนี้มันกว้างใหญ่เกินไปล่ะ?"
L44_1.m_Talk_THA = L45_1
L45_1 = "Ừ, cô nghĩ sao nếu tôi nói tôi làm thế vì vũ trụ quá rộng lớn?"
L44_1.m_Talk_VTN = L45_1
L45_1 = "那么，我说是因为宇宙太宽广了怎么样？"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Ja, wie wäre es dann damit, dass das Universum zu groß ist?"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Oui, par exemple, et si je le faisais parce que l'univers est trop vaste ?"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
