L47_1 = "EP5_ACT5_STAGE4_START@46#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 46
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 208
L46_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L46_1.m_Pos = "C"
L47_1 = 40
L46_1.m_Crash = L47_1
L47_1 = "그게 무슨 헛소리야? 지금 나랑 장난하자는 거야?!"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "そんな冗談言ってる場合？　ふざけてるの！？"
L46_1.m_Talk_JPN = L47_1
L47_1 = "You've got to be kidding me. Is this a joke to you?"
L46_1.m_Talk_ENG = L47_1
L47_1 = "這是什麼鬼話？你在和我開玩笑嗎？！"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ล้อเล่นใช่ไหม คุณมองว่านี่มันเรื่องตลกเหรอ?"
L46_1.m_Talk_THA = L47_1
L47_1 = "Ông đùa tôi đấy à. Đây có phải là trò đùa với bạn không?"
L46_1.m_Talk_VTN = L47_1
L47_1 = "那是什么鬼话啊？你在和我开玩笑吗？！"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Du willst mich wohl auf den Arm nehmen! Ist das für dich alles ein Witz?"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Vous devez vous moquer de moi. Tout ça c'est un jeu pour vous ?"
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "EP5_ACT5_STAGE4_START@47#Talk"
