L48_1 = 47
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 208
L47_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_Face = "UNIT_IDLE"
L48_1 = "CUTSCENE_TALK_02"
L47_1.m_StartBGMFileName = L48_1
L47_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L47_1.m_Pos = "C"
L48_1 = "헛소리가 아닐세. 진심이지."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "冗談ではない、本心だ。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "No, it's not a joke. I'm being serious."
L47_1.m_Talk_ENG = L48_1
L48_1 = "這不是鬼話，我是認真的。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "เปล่า ไม่ใช่เรื่องตลก ผมจริงจังนะ"
L47_1.m_Talk_THA = L48_1
L48_1 = "Không, đó không phải là một trò đùa. Tôi đang nghiêm túc."
L47_1.m_Talk_VTN = L48_1
L48_1 = "不是瞎说的哦。是我的真心话。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Nein, im Gegenteil. Es ist mir ernst."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Non, ce n'est pas un jeu. Je suis sérieux."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "EP5_ACT5_STAGE4_START@48#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 48
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 208
L48_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L48_1.m_Pos = "C"
L49_1 = "만약 우주가 조금만 더 좁았다면......"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "もし宇宙がもう少し狭かったなら……"
L48_1.m_Talk_JPN = L49_1
L49_1 = "If the universe were a little bit smaller..."
L48_1.m_Talk_ENG = L49_1
L49_1 = "要是宇宙能小一點的話……"
L48_1.m_Talk_TWN = L49_1
L49_1 = "หากจักรวาลเล็กกว่านี้สักหน่อย..."
L48_1.m_Talk_THA = L49_1
L49_1 = "Nếu vũ trụ nhỏ hơn một chút..."
L48_1.m_Talk_VTN = L49_1
L49_1 = "要是宇宙再小一点的话……"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Wenn das Universum nur ein bisschen kleiner wäre …"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Si l'univers était un petit peu plus petit..."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "EP5_ACT5_STAGE4_START@49#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 49
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 208
L49_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L49_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L49_1.m_Pos = "C"
L50_1 = "그래서 인류가 다른 행성으로 도망갈 수 있다는 아주 약간의 희망이라도 있었다면, 나도 이런 극단적인 방법을 쓰지는 않았을 테지."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "それで人類が別の惑星へ避難できるという、ごくわずかな希望さえ持てたなら、\n私もこんな極端な手段は使わなかっただろう。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "and there were a tiny bit of hope that mankind could escape to another planet, I wouldn't have taken these extreme measures."
L49_1.m_Talk_ENG = L50_1
L50_1 = "那麼人類就有逃到其他行星、非常微小的一絲希望，我也就不會使用這種極端的方法了。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "และหากมนุษยชาติยังพอมีความหวังสักนิดว่าจะหลบหนีไปยังดาวดวงอื่นได้ ผมก็คงไม่ต้องใช้มาตรการที่สุดขั้วขนาดนี้"
L49_1.m_Talk_THA = L50_1
L50_1 = "và có một chút hy vọng nhỏ nhoi rằng nhân loại có thể trốn đến một hành tinh khác, tôi sẽ không thực hiện những biện pháp cực đoan này."
L49_1.m_Talk_VTN = L50_1
L50_1 = "那么人类就有一星半点的希望逃亡其他行星，我也就不用使用这种极端的办法了。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "und auch nur die geringste Chance bestünde, dass die Menschheit andere Planeten erreichen kann, hätte ich nicht zu solch extremen Mitteln gegriffen."
L49_1.m_Talk_DEU = L50_1
L50_1 = "et qu'il y avait ne serait-ce qu'un mince espoir que l'humanité puisse s'enfuir vers une autre planète, je n'aurais pas pris ces mesures extrêmes."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "EP5_ACT5_STAGE4_START@50#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L50_1.m_CutScenProcessKey = 50
L50_1.m_CutScenID = 208
L50_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L50_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L50_1.m_Pos = "C"
L51_1 = "다른 행성? 도망을 간다......?"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "別の惑星？　避難……？"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Escape to another planet?"
L50_1.m_Talk_ENG = L51_1
L51_1 = "其他行星？逃跑……？"
L50_1.m_Talk_TWN = L51_1
L51_1 = "หนีไปยังดาวดวงอื่นเหรอ?"
L50_1.m_Talk_THA = L51_1
L51_1 = "Trốn đến hành tinh khác?"
L50_1.m_Talk_VTN = L51_1
L51_1 = "其他行星？逃跑……？"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Andere Planeten erreichen?"
L50_1.m_Talk_DEU = L51_1
L51_1 = "S'enfuir vers une autre planète ?"
L50_1.m_Talk_FRA = L51_1
