L2_1 = "EP5_ACT5_STAGE4_START@51#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 51
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 208
L1_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L1_1.m_Face = "UNIT_DESPAIR"
L1_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L1_1.m_Pos = "C"
L2_1 = "하지만...... 현실은 가혹하지."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "だが……現実は厳しい。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "However... the reality is harsh."
L1_1.m_Talk_ENG = L2_1
L2_1 = "但是……現實很殘酷。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ทว่า... ความเป็นจริงช่างโหดร้าย"
L1_1.m_Talk_THA = L2_1
L2_1 = "Tuy nhiên... thực tế phũ phàng."
L1_1.m_Talk_VTN = L2_1
L2_1 = "但是……现实很残酷。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Nun … die Realität sieht bekanntlich anders aus."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Mais... la réalité est cruelle."
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "EP5_ACT5_STAGE4_START@52#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 52
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 208
L2_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L2_1.m_Pos = "C"
L3_1 = "이터니움 드라이브가 실용화된 현재의 우주항해 기술로도 가장 가까운 프록시마 센타우리까지 최소한 10만년 이상이 걸려."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "エタニウムドライブが実用化した現在の宇宙航海技術でも、\n最も近いプロキシマ・ケンタウリまで、最低でも10万年以上かかる。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "The space technology has advanced to the point that we're utilizing Eternium Drive to power our ships, but it still takes at least a hundred thousand years to get to Proxima Centauri."
L2_1.m_Talk_ENG = L3_1
L3_1 = "即使是在現在，以永恆之金引擎實用化的宇宙航行技術，我們要到達最近的比鄰星，最少也會拖個10萬年以上。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "เทคโนโลยีอวกาศพัฒนามาจนถึงจุดที่เราใช้อีเทอร์เนียมไดรฟ์สร้างพลังงานให้กับยานของเรา แต่เรายังต้องใช้เวลาอีกอย่างน้อยแสนปีกว่าจะไปถึงกลุ่มดาวพร็อกซิมาคนครึ่งม้า"
L2_1.m_Talk_THA = L3_1
L3_1 = "Công nghệ vũ trụ đã phát triển đến mức chúng tôi đang sử dụng Động Cơ Vàng Vĩnh Cửu để cung cấp năng lượng cho các con tàu của mình, nhưng vẫn phải mất ít nhất một trăm nghìn năm để đến Proxima Centauri."
L2_1.m_Talk_VTN = L3_1
L3_1 = "即使运用能晶引擎的宇宙航海技术，到最近的比邻星最少也要10万年以上。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Die Weltraumtechnik hat sich zwar etwas weiterentwickelt, schließlich haben wir den Eternium-Antrieb, aber es dauert immer noch hunderttausend Jahre, bis wir Proxima Centauri erreichen."
L2_1.m_Talk_DEU = L3_1
L3_1 = "La technologie spatiale nous a offert la propulsion à l'éternium pour nos vaisseaux, mais malgré cela il faut encore au moins cent mille ans pour se rendre sur Proxima du Centaure."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "EP5_ACT5_STAGE4_START@53#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 53
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 208
L3_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L3_1.m_Pos = "C"
L4_1 = "SF 소설에는 수백만 년을 항해하는 세대 우주선의 이야기도 흔하게 나오지만......"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "SF小説には数百万年を航海する宇宙船の話も頻繁に登場するが……"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Science fiction tells of space ships that navigate for millions of years,"
L3_1.m_Talk_ENG = L4_1
L4_1 = "儘管科幻小說中經常出現航行數百萬年的世代太空船……"
L3_1.m_Talk_TWN = L4_1
L4_1 = "นิยายวิทยาศาสตร์พูดถึงยานอวกาศที่เดินทางได้เป็นล้านๆ ปี"
L3_1.m_Talk_THA = L4_1
L4_1 = "Khoa học viễn tưởng kể về những con tàu không gian có thể di chuyển hàng triệu năm,"
L3_1.m_Talk_VTN = L4_1
L4_1 = "虽然科幻小说中经常出现航行数百万年的世代宇宙飞船的故事……"
L3_1.m_Talk_SCN = L4_1
L4_1 = "In der Science-Fiction gibt es Raumschiffe, die Millionen Jahre unterwegs sind,"
L3_1.m_Talk_DEU = L4_1
L4_1 = "La science-fiction nous parle de vaisseaux spatiaux capables de naviguer pendant des millions d'années,"
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "EP5_ACT5_STAGE4_START@54#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 54
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 208
L4_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L4_1.m_Pos = "C"
L5_1 = "실제로 인류는 백 년 동안 동작하는 기계도 만들어 본 적이 없네."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "実際には、人類は百年間作動する機械すら創り出したことがない。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "but in reality, mankind hasn't even made a single mechanical part that continues working for a hundred years,"
L4_1.m_Talk_ENG = L5_1
L5_1 = "但是實際上，人類連能夠運轉一百年的機器都沒造出來過。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "แต่ในความเป็นจริง มนุษยชาติยังไม่เคยสร้างอะไหล่เครื่องยนต์ที่ทำงานต่อเนื่องได้ถึงร้อยปีเลย"
L4_1.m_Talk_THA = L5_1
L5_1 = "nhưng trên thực tế, loài người thậm chí còn chưa tạo ra một bộ phận cơ khi nào có thể liên tục hoạt động trong một trăm năm,"
L4_1.m_Talk_VTN = L5_1
L5_1 = "但是实际上人类连能够运转百年以上的机器都没有创造出来过。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "aber in Wirklichkeit haben die Menschen noch nicht ein einziges mechanisches Bauteil erschaffen, dass auch nur einhundert Jahre funktioniert,"
L4_1.m_Talk_DEU = L5_1
L5_1 = "mais dans les faits, l'humanité n'a même pas su créer un seul mécanisme qui fonctionne plus de cent ans,"
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "EP5_ACT5_STAGE4_START@55#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 55
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 208
L5_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L5_1.m_Pos = "C"
L6_1 = "하물며 수십만 년을 오차 없이 날아가야 하는 우주선은 말할 것도 없지."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "ましてや、数十万年を誤差なく飛ばなければならない宇宙船は言うまでもない。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "let alone a space ship sturdy enough to last a hundred thousand-year journey."
L5_1.m_Talk_ENG = L6_1
L6_1 = "更何況是要無誤差地航行數十萬年的太空船。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ยังไม่ต้องพูดถึงยานรบที่ทนทานพอที่จะผ่านการเดินทางหนึ่งแสนปีได้"
L5_1.m_Talk_THA = L6_1
L6_1 = "chứ đừng nói đến một con tàu không gian đủ vững chãi để thực hiệni một hành trình trăm nghìn năm."
L5_1.m_Talk_VTN = L6_1
L6_1 = "更何况是要无误差地航行数十万年的宇宙飞船。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "ganz zu schweigen von Raumschiffen, die eine Reise von hunderttausend Jahren überstehen könnten."
L5_1.m_Talk_DEU = L6_1
L6_1 = "et encore moins de vaisseau spatial suffisamment robuste pour endurer un voyage de cent mille ans."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "EP5_ACT5_STAGE4_START@56#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 56
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 208
L6_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L6_1.m_Pos = "C"
L7_1 = "심지어는 그렇게 도착한 곳에 인류가 살 만한 행성이 있다고 확신할 수 있는 것도 아니야."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "しかも、もしたどり着いたとしても、そこに人類が生き延びれる惑星があるとは限らない。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Worse, even if we were to make it there in one piece, there's no guarantee that there would be a planet with a habitable environment."
L6_1.m_Talk_ENG = L7_1
L7_1 = "再加上，我們也無法確定到達的地方，是不是人類可以居住的行星。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ที่แย่กว่านั้นคือ ต่อให้เราไปถึงที่นั่นได้อย่างปลอดภัย ก็ไม่มีอะไรรับประกันว่าจะมีดาวเคราะห์ที่มีสภาพแวดล้อมที่เหมาะแก่การอยู่อาศัย"
L6_1.m_Talk_THA = L7_1
L7_1 = "Tệ hơn nữa, ngay cả khi chúng ta có nó, không có gì đảm bảo rằng sẽ có một hành tinh có môi trường mà chúng ta có thể sống được."
L6_1.m_Talk_VTN = L7_1
L7_1 = "而且也无法确定到达的地方是不是人类可以居住的行星。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Schlimmer noch: Selbst wenn wir diese Reise unbeschadet überstehen könnten, gäbe es keine Garantie, auf bewohnbare Planeten zu stoßen."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Et le pire, c'est que même si nous étions capables de nous rendre jusque-là-bas en un seul morceau, rien ne nous garantirait la présence d'une planète habitable."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "EP5_ACT5_STAGE4_START@57#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 57
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 208
L7_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L7_1.m_Pos = "C"
L8_1 = "이래서야...... 전혀 희망이 없다고 해야 하지 않겠나?"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "これでは……まったくもって希望がないじゃないか。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "This is a truly hopeless situation for all of us."
L7_1.m_Talk_ENG = L8_1
L8_1 = "這樣……我們不就是毫無希望嗎？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "นี่เป็นสถานการณ์ที่สิ้นหวังสำหรับเราทั้งหมดอย่างแท้จริง"
L7_1.m_Talk_THA = L8_1
L8_1 = "Đây là một tình huống thực sự vô vọng đối với tất cả chúng ta."
L7_1.m_Talk_VTN = L8_1
L8_1 = "就是因为这样……才毫无希望的不是吗？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Die Situation ist schlicht hoffnungslos."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Notre situation est bel et bien désespérée."
L7_1.m_Talk_FRA = L8_1
