L9_1 = "你……你在說什麼啊？！"
L8_1.m_Talk_TWN = L9_1
L9_1 = "พะ-พูดอะไรของคุณน่ะ?"
L8_1.m_Talk_THA = L9_1
L9_1 = "Ông đang nói cái quái gì vậy?"
