L10_1 = "EP5_ACT5_STAGE4_START@59#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 59
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 208
L9_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
