L9_1.m_Pos = "C"
L10_1 = "우주 항해니, 프록시마 센타우리니...... 하나도 못 알아듣겠어!!"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "宇宙航海とか、プロキシマ・ケンタウリとか……さっぱりわからないよ！！"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Space ships, Proxima Centauri... I don’t understand any of it!"
L9_1.m_Talk_ENG = L10_1
L10_1 = "什麼宇宙航行、比鄰星……我一個字都聽不懂！！"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ยานอวกาศ กลุ่มดาวพร็อกซิมาคนครึ่งม้า... ฉันไม่เห็นเข้าใจเลย!"
L9_1.m_Talk_THA = L10_1
L10_1 = "Tàu không gian, Proxima Centauri... Tôi không hiểu gì cả!"
L9_1.m_Talk_VTN = L10_1
L10_1 = "什么宇宙航行、比邻星……我都没有听懂！！"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Raumschiffe, Proxima Centauri … Das versteht ja kein Mensch!"
L9_1.m_Talk_DEU = L10_1
L10_1 = "Vaisseaux spatiaux, Proxima du Centaure... Je n'y comprends rien du tout !"
L9_1.m_Talk_FRA = L10_1
