L19_1.m_Pos = "C"
L20_1 = "막을 수도, 피할 수도 없는 절대적인 종말이......"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "防ぐことも、避けることもできない、絶対的な終末が……"
L19_1.m_Talk_JPN = L20_1
L20_1 = "And it can't be stopped or avoided."
L19_1.m_Talk_ENG = L20_1
L20_1 = "無法阻止也無法逃避的絕對末日……"
L19_1.m_Talk_TWN = L20_1
L20_1 = "และเราหยุดหรือหลีกเลี่ยงมันไม่ได้"
L19_1.m_Talk_THA = L20_1
L20_1 = "Và không ai có thể tránh được hay ngăn chặn nó."
L19_1.m_Talk_VTN = L20_1
L20_1 = "无法阻止也无法逃避的末日……"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Und er naht unausweichlich."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Et on ne peut pas l'arrêter, ni l'éviter."
L19_1.m_Talk_FRA = L20_1
