L21_1 = "무슨...... 사이비나 믿을 것 같은 거짓말을......"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "そんな……宗教じみた嘘を……"
L20_1.m_Talk_JPN = L21_1
L21_1 = "That's a pathetic lie that only brainless cult followers would fall for."
L20_1.m_Talk_ENG = L21_1
L21_1 = "這是什麼……傻子才會信的謊話。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "นั่นเป็นคำโกหกน่าสมเพชที่มีแต่คนคลั่งลัทธิที่ไร้สมองเท่านั้นที่จะเชื่อ"
L20_1.m_Talk_THA = L21_1
L21_1 = "Đó là một lời nói dối thảm hại mà chỉ những kẻ cuồng tín thiểu não mới tin."
L20_1.m_Talk_VTN = L21_1
L21_1 = "这是什么……傻子才会信的谎话。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Auf so eine lächerliche Lüge fallen doch nur hirnlose Sektenanhänger rein."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Il n'y a que les adeptes décérébrés de votre secte qui peuvent croire un mensonge pareil."
L20_1.m_Talk_FRA = L21_1
