L22_1 = "거짓말이 아닐세. 내가 대정화 전쟁 참전자라는 건 알고 있겠지?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "嘘ではない、私が大浄化戦争に参戦していたことは知ってるだろう？"
L21_1.m_Talk_JPN = L22_1
L22_1 = "I'm not lying. You know I fought in the Grand Purification War, don't you?"
L21_1.m_Talk_ENG = L22_1
L22_1 = "不是謊話。妳知道我是淨化之戰的參戰者吧？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "ผมไม่ได้โกหกนะ คุณก็รู้ว่าผมเคยต่อสู้ในมหาสงครามแห่งการชำระล้างใช่ไหม?"
L21_1.m_Talk_THA = L22_1
L22_1 = "Tôi không nói dối. Bạn biết tôi đã chiến đấu trong Cuộc Chiến Đại Thanh Lọc, phải không?"
L21_1.m_Talk_VTN = L22_1
L22_1 = "不是谎话。你知道我是净化之战的参战者吧？"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Ich lüge nicht. Du weißt doch sicher, dass ich im Großen Läuterungskrieg gekämpft habe?"
L21_1.m_Talk_DEU = L22_1
L22_1 = "Je ne mens pas. Vous savez que j'ai combattu durant la Grande guerre de purification, n'est-ce pas ?"
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "EP5_ACT5_STAGE4_START@72#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 72
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 208
L22_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L22_1.m_Pos = "C"
L23_1 = "전쟁에 참전하는 동안 난 일종의 정보장교 역할을 맡았었네."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "戦時中、私は情報将校のような役割をしていた。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "During the war, I served as an intelligence officer."
L22_1.m_Talk_ENG = L23_1
L23_1 = "參戰的時候，我擔任的是某種情報將校。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ระหว่างสงคราม ผมทำหน้าที่เป็นเจ้าหน้าที่หน่วยข่าวกรอง"
L22_1.m_Talk_THA = L23_1
L23_1 = "Trong chiến tranh, tôi là sĩ quan tình báo."
L22_1.m_Talk_VTN = L23_1
L23_1 = "参战的时候我是情报军官。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Ich diente damals im Geheimdienst."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Pendant la guerre, j'ai servi en tant qu'officier du renseignement."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "EP5_ACT5_STAGE4_START@73#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 73
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 208
L23_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L23_1.m_Pos = "C"
L24_1 = "이면세계에 남겨진 다양한 정보와 기록들을 수집해서 침식체들에 대항할 방법을 찾는 그런 일이었지."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "裏世界に残された様々な情報や記録を収集し、侵食体の対応策を探す仕事だった。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "I was in charge of collecting various information and records from the Counterside to find a way to deal with the C.O.s."
L23_1.m_Talk_ENG = L24_1
L24_1 = "我負責收集和異界有關的各種情報和紀錄，然後找出對抗侵蝕體的方法。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ผมดูแลเรื่องการเก็บข้อมูลและสถิติต่างๆ จากเคาน์เตอร์ไซด์ เพื่อหาวิธีรับมือกับวัตถุคอร์รัปต์"
L23_1.m_Talk_THA = L24_1
L24_1 = "Tôi chịu trách nhiệm thu thập các thông tin và hồ sơ khác nhau từ Counter để tìm cách đối phó với V.T.B.A.M"
L23_1.m_Talk_VTN = L24_1
L24_1 = "我负责收集和异界有关的各种信息和情报，然后找到对抗侵蚀体的方法。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Meine Aufgabe war es, Daten und Aufzeichnungen von der Counterside zu sammeln, um irgendwie mit den C. O.s fertigwerden zu können."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Mon rôle était de recueillir diverses informations et données en provenance du Contremonde afin de trouver un moyen de lutter contre les O.C."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "EP5_ACT5_STAGE4_START@74#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 74
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 208
L24_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L24_1.m_Pos = "C"
L25_1 = "하지만...... 그 일을 진행하면서 난 전혀 예상하지 못한 다른 진실을 알아버리고 말았네."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "だが……私はその仕事中に、まったく想定外の、別の真実を知ってしまったんだ。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "But... through my operations, I came to learn a truth, and a very unexpected one at that."
L24_1.m_Talk_ENG = L25_1
L25_1 = "但是……在我執行任務的同時，我發現了我完全沒有預想到的真相。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "แต่... ในปฏิบัติการต่างๆ ผมก็ได้เรียนรู้ความจริง เป็นความจริงที่เหนือความคาดหมาย"
L24_1.m_Talk_THA = L25_1
L25_1 = "Nhưng ... thông qua các hoạt động của mình, tôi đã biết được một sự thật, và một sự thật rất bất ngờ."
L24_1.m_Talk_VTN = L25_1
L25_1 = "但是……在我执行任务的同时我发现了完全预想不到的真相。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Doch … dabei stieß ich auf die Wahrheit. Eine sehr unerwartete Wahrheit obendrein."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Mais... au cours de mes opérations, j'ai appris une vérité, et une vérité très inattendue qui plus est."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "EP5_ACT5_STAGE4_START@75#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L25_1.m_CutScenProcessKey = 75
L25_1.m_CutScenID = 208
L25_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L25_1.m_Pos = "C"
L26_1 = "전혀 다른 진실이라...... 그게 뭐죠?"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "まったく想定外の真実……それは何でしょう？"
L25_1.m_Talk_JPN = L26_1
L26_1 = "An unexpected truth, huh... What was it?"
L25_1.m_Talk_ENG = L26_1
L26_1 = "完全沒有預想到的真相……那是什麼？"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ความจริงที่เหนือความคาดหมายเหรอ... มันคืออะไร?"
L25_1.m_Talk_THA = L26_1
L26_1 = "Một sự thật bất ngờ, hử... Đó là gì?"
L25_1.m_Talk_VTN = L26_1
L26_1 = "完全预想不到的真相吗……是什么？"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Aha. Eine unerwartete Wahrheit. Und die wäre?"
L25_1.m_Talk_DEU = L26_1
L26_1 = "Une vérité inattendue, hein... C'était quoi ?"
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "EP5_ACT5_STAGE4_START@76#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 76
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 208
L26_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L26_1.m_Pos = "C"
L27_1 = "자네들은 이면세계가 뭐라고 생각하나?"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "君たちは裏世界のことを何だと思ってる？"
L26_1.m_Talk_JPN = L27_1
L27_1 = "What do you think the Counterside is?"
L26_1.m_Talk_ENG = L27_1
L27_1 = "你們覺得異界是什麼？"
L26_1.m_Talk_TWN = L27_1
L27_1 = "คุณคิดว่าเคาน์เตอร์ไซด์คืออะไร?"
L26_1.m_Talk_THA = L27_1
L27_1 = "Bạn nghĩ Counterside là gì?"
L26_1.m_Talk_VTN = L27_1
L27_1 = "你们觉得异界是什么？"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Was, denkst du, ist die Counterside?"
L26_1.m_Talk_DEU = L27_1
L27_1 = "Le Contremonde... Qu'est-il, à votre avis ?"
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "EP5_ACT5_STAGE4_START@77#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 77
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 208
L27_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L27_1.m_Pos = "C"
L28_1 = "어째서 이면세계에는 마치 인간이 만든 것 같은 버려진 도시와 유적들이 존재하는 거지?"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "どうして裏世界には、まるで人間が建てたような都市や遺跡が放置されているんだ？"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Why are there abandoned cities and ruins that look like they were built by mankind?"
L27_1.m_Talk_ENG = L28_1
L28_1 = "為什麼異界裡會有像是人類建造的廢棄都市和遺跡呢？"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ทำไมถึงมีเมืองร้างและซากปรักหักพังที่ดูเหมือนถูกมนุษย์สร้างขึ้น?"
L27_1.m_Talk_THA = L28_1
L28_1 = "Tại sao ở đó có những thành phố bị bỏ hoang và tàn tích trông giống như được loài người dựng nên?"
L27_1.m_Talk_VTN = L28_1
L28_1 = "异界里怎么会有看上去像是人类创造的城市和遗迹的呢？"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Warum gibt es dort verlassene Städte und Ruinen, die menschengemacht aussehen?"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Pourquoi y trouve-t-on des cités abandonnées et des ruines qui laissent à penser qu'elles ont été bâties des mains de l'homme ?"
L27_1.m_Talk_FRA = L28_1
