L29_1.m_Pos = "C"
L30_1 = "그건 이면세계가 바로 멸망한 세계의 잔재이기 때문이다."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "それはつまり、裏世界が滅亡した世界の残骸だからだ。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "It's because the Counterside is the vestiges of the worlds that existed before."
L29_1.m_Talk_ENG = L30_1
L30_1 = "因為異界就是滅亡的世界殘餘。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "นั่นก็เพราะเคาน์เตอร์ไซด์คือเศษซากของโลกเก่าที่เคยมีอยู่ไงล่ะ"
L29_1.m_Talk_THA = L30_1
L30_1 = "Đó là bởi vì Counterside là dấu tích của những thế giới tồn tại trước đây."
L29_1.m_Talk_VTN = L30_1
L30_1 = "因为异界就是灭亡了的世界的遗迹。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Weil es sich bei der Counterside um Überreste von früheren Welten handelt."
L29_1.m_Talk_DEU = L30_1
L30_1 = "C'est parce que le Contremonde est le vestige des mondes qui existaient auparavant."
L29_1.m_Talk_FRA = L30_1
