L34_1 = "그것도 한 번, 두 번이 아니야."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "しかも、一回や二回ではない。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "And it hasn't happened just once."
L33_1.m_Talk_ENG = L34_1
L34_1 = "那也不是一兩次的事情。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "และมันไม่ได้เกิดขึ้นแค่ครั้งเดียวนะ"
