L35_1 = "다양한 심도와 좌표로 나뉘어진 이면세계들......"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "様々な深度や座標で分かれている裏世界……"
L34_1.m_Talk_JPN = L35_1
L35_1 = "There are several Counterside worlds at different depths and coordinates,"
L34_1.m_Talk_ENG = L35_1
L35_1 = "被分為不同深度和座標的異界……"
L34_1.m_Talk_TWN = L35_1
L35_1 = "มีโลกเคาน์เตอร์ไซด์มากมายที่ระดับความลึกและพิกัดต่างกัน"
L34_1.m_Talk_THA = L35_1
L35_1 = "Có một số thế giới Counterside ở các độ sâu và tọa độ khác nhau,"
L34_1.m_Talk_VTN = L35_1
L35_1 = "被分为不同的深度和坐标的异界……"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Es gibt verschiedene Counterside-Welten in verschiedenen Tiefen und Koordinaten …"
L34_1.m_Talk_DEU = L35_1
L35_1 = "Le Contremonde présente une multitude d'univers à différentes coordonnées et profondeurs,"
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "EP5_ACT5_STAGE4_START@85#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 85
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 208
L35_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L36_1 = "그것들 각각이 모두 별개의 멸망한 세계들이지."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "それらすべてが、滅亡した個別の世界だ。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "and every single one of them is a world after the apocalypse."
L35_1.m_Talk_ENG = L36_1
L36_1 = "它們各自就是不同的滅亡世界。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "และแต่ละโลกก็คือโลกหลังวันโลกาวินาศ"
L35_1.m_Talk_THA = L36_1
L36_1 = "và mỗi thế giới trong đó là một thế giới sau ngày tận thế."
L35_1.m_Talk_VTN = L36_1
L36_1 = "就是不同的灭亡的世界。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "und bei jeder einzelnen handelt es sich um eine Welt nach der Apokalypse."
L35_1.m_Talk_DEU = L36_1
L36_1 = "et chacun d'entre eux est un monde qui a subi l'apocalypse."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "EP5_ACT5_STAGE4_START@86#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 86
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 208
L36_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L37_1 = "그중에는 우리와 극히 비슷한 문명도, 전혀 다른 문명도 있지만......"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "なかには我々と酷似している文明も、まったく別の文明もあったが……"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Some of them had civilizations similar to ours, and some different,"
L36_1.m_Talk_ENG = L37_1
L37_1 = "在那之中，有和我們極其相似的文明，也有完全不一樣的文明……"
L36_1.m_Talk_TWN = L37_1
L37_1 = "บางแห่งมีอารยธรรมที่คล้ายกับเรา บางแห่งก็แตกต่าง"
L36_1.m_Talk_THA = L37_1
L37_1 = "Một vài thế giới này có nền văn minh tương tự như chúng ta, và một vài thế giới có nền văn minh khác,"
L36_1.m_Talk_VTN = L37_1
L37_1 = "在那之中有和我们类似的文明，还有完全不一样的文明……"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Einige von ihnen beherbergten Zivilisationen, die unseren ähnlich waren, andere nicht,"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Certains avaient des civilisations semblables à la nôtre, et d'autres totalement différentes,"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "EP5_ACT5_STAGE4_START@87#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 87
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 208
L37_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L38_1 = "그 어떤 세계도 멸망하여 <color=#ffd34c>이면화</color>되는 운명을 피할 수 없었어."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "いずれの世界も、滅亡して<color=#ffd34c>裏世界化</color>する運命から逃れることはできなかった。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "but none of them were able to escape the doom that came before the <color=#ffd34c>Counterization</color>."
L37_1.m_Talk_ENG = L38_1
L38_1 = "不管是什麼樣的世界，都無法避免滅亡後<color=#ffd34c>異界化</color>的命運。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "แต่ไม่มีที่ไหนรอดจากหายนะที่มาถึงก่อน<color=#ffd34c>การเคาน์เตอร์</color>"
L37_1.m_Talk_THA = L38_1
L38_1 = "nhưng không thế giới nào trong đó có thể thoát khỏi sự diệt vong xảy ra trước <color=#ffd34c>sự kiện Counterization</color>."
L37_1.m_Talk_VTN = L38_1
L38_1 = "不管是什么样的世界都无法避免灭亡之后<color=#ffd34c>异界化</color>的命运。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "aber keine von ihnen konnte dem Untergang vor der <color=#ffd34c>Counterisierung</color> entgehen."
L37_1.m_Talk_DEU = L38_1
L38_1 = "mais aucun d'entre eux n'a pu échapper au funeste destin qui a précédé la <color=#ffd34c>Counterisation</color>."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "EP5_ACT5_STAGE4_START@88#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 88
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 208
L38_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L39_1 = "그리고 이제는...... 우리 차례가 다가오고 있다."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "そして今度は……私たちの番が近づいている。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "And now, the end is coming to our world."
L38_1.m_Talk_ENG = L39_1
L39_1 = "然後現在……快要輪到我們了。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "และตอนนี้จุดจบกำลังจะมาสู่โลกของเรา"
L38_1.m_Talk_THA = L39_1
L39_1 = "Và bây giờ, kết thúc đang đến với thế giới của chúng ta."
L38_1.m_Talk_VTN = L39_1
L39_1 = "现在……轮到我们了。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Und jetzt steht unserer Welt der Untergang bevor."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Et maintenant, la fin de notre monde approche."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
