L44_1 = "그래서...... 도망칠 방법을 구상한 겁니까?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "それで……逃げる方法を考えたのですか？"
L43_1.m_Talk_JPN = L44_1
L44_1 = "And... you were trying to devise a plan to flee?"
L43_1.m_Talk_ENG = L44_1
L44_1 = "所以……你想出逃跑的方法了嗎？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "แล้ว... คุณเลยพยายามคิดแผนหลบหนีงั้นเหรอ?"
L43_1.m_Talk_THA = L44_1
L44_1 = "Và... bạn đang cố gắng nghĩ ra một kế hoạch để chạy trốn sao?"
L43_1.m_Talk_VTN = L44_1
L44_1 = "所以……你们想到逃跑的方法了吗？"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Und … Du hast einen Fluchtplan entwickelt?"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Alors... vous avez essayé d'élaborer un plan pour en échapper ?"
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "EP5_ACT5_STAGE4_START@94#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 94
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 208
L44_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L44_1.m_Pos = "L"
L45_1 = "리플레이서는 그 방법의 일부인 거고?"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "リプレイサーは、その方法の一部だと？"
L44_1.m_Talk_JPN = L45_1
L45_1 = "And creating the Replacers was a part of it?"
L44_1.m_Talk_ENG = L45_1
L45_1 = "克隆集團就是那個方法的一部分？"
L44_1.m_Talk_TWN = L45_1
L45_1 = "และการสร้างรีเพลสเซอร์ก็เป็นส่วนหนึ่งในแผนนั้น?"
L44_1.m_Talk_THA = L45_1
L45_1 = "Và tạo ra Người Nhân Bản là một phần của kế hoạch đó?"
L44_1.m_Talk_VTN = L45_1
L45_1 = "克隆集团就是那个方法的一部分？"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Und die Schaffung der Replacer war Teil davon?"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Et la création des substituts en faisait partie ?"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
