L46_1.m_Pos = "C"
L47_1 = "그래."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "そうだ。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Precisely."
L46_1.m_Talk_ENG = L47_1
L47_1 = "是的。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ถูกต้อง"
L46_1.m_Talk_THA = L47_1
L47_1 = "Chính xác."
L46_1.m_Talk_VTN = L47_1
L47_1 = "没错。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Genau."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Précisément."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "EP5_ACT5_STAGE4_START@97#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 97
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 208
L47_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L47_1.m_Pos = "C"
L48_1 = "이 세계는 곧 멸망한다. 하지만 우주로 도망칠 수는 없지. 그건 불가능하니까."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "この世界はもうじき滅亡する。だが、宇宙に逃げることは不可能だ。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "This world will end soon. And we can't flee to outer space. Our technologies are just not advanced enough."
L47_1.m_Talk_ENG = L48_1
L48_1 = "這個世界馬上會滅亡，但是我們又無法逃向宇宙，因為那是不可能的。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "โลกนี้ใกล้จะจบลงแล้ว และเราหนีไปอวกาศไม่ได้ เทคโนโลยีของเรายังไม่ก้าวหน้าพอ"
L47_1.m_Talk_THA = L48_1
L48_1 = "Thế giới này sẽ sớm kết thúc. Và chúng ta không thể chạy trốn ra không gian bên ngoài. Công nghệ của chúng ta không đủ tiên tiến để làm việc đó."
L47_1.m_Talk_VTN = L48_1
L48_1 = "这个世界一定会灭亡。但是我们无法逃向宇宙。因为那是不可能的。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Diese Welt wird bald enden. Auf andere Planeten flüchten können wir nicht. Dazu ist unsere Technologie nicht fortgeschritten genug."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Ce monde touche à sa fin, et nous ne pouvons pas nous enfuir aux confins de l'univers. Notre technologie n'est pas assez avancée."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "EP5_ACT5_STAGE4_START@98#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 98
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 208
L48_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L48_1.m_Pos = "C"
L49_1 = "그래서 나는...... 이면세계로 도망치기로 했다."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "そこで私は……裏世界に逃げることにしたんだ。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "So I decided that the Counterside would be our shelter."
L48_1.m_Talk_ENG = L49_1
L49_1 = "所以我決定……逃往異界。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ผมเลยตัดสินใจว่าเคาน์เตอร์ไซด์จะเป็นที่หลบภัยของเรา"
L48_1.m_Talk_THA = L49_1
L49_1 = "Vì vậy, tôi quyết định rằng Counterside sẽ là nơi trú ẩn của chúng tôi."
L48_1.m_Talk_VTN = L49_1
L49_1 = "所以我决定……逃往异界。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Daher kam ich zu dem Schluss, dass uns die Counterside Schutz gewähren würde."
L48_1.m_Talk_DEU = L49_1
L49_1 = "J'ai donc décidé que le Contremonde serait notre refuge."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "EP5_ACT5_STAGE4_START@99#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 99
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 208
L49_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L49_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L49_1.m_Pos = "C"
L50_1 = "그곳이야말로 인류가 현실적으로 도달할 수 있는 유일한 피난처니까."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "そこは、人類が実際に到達できる、唯一の避難先だからな。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Because that was the only place left for mankind to go."
L49_1.m_Talk_ENG = L50_1
L50_1 = "那是人類在現實中，可以到達的唯一避難所。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "เพราะนั่นเป็นที่เดียวที่มนุษยชาติสามารถไปได้"
L49_1.m_Talk_THA = L50_1
L50_1 = "Bởi vì đó là nơi duy nhất còn lại của loài người."
L49_1.m_Talk_VTN = L50_1
L50_1 = "那是人类唯一可以到达的避难所。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Denn sie ist der einzige für die Menschen noch erreichbare Ort."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Car c'était le seul endroit accessible à l'humanité."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
