L1_1.m_Pos = "C"
L2_1 = "인간은 이면세계에서 장시간 버티지 못해."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "人間は裏世界で長時間耐えられないんだ。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "We can't last long in the Counterside."
L1_1.m_Talk_ENG = L2_1
L2_1 = "人類無法長時間待在異界。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "เราอยู่ในเคาน์เตอร์ไซด์นานๆ ไม่ได้"
L1_1.m_Talk_THA = L2_1
L2_1 = "Chúng ta không thể tồn tại lâu ở Counterside."
L1_1.m_Talk_VTN = L2_1
L2_1 = "人类无法长时间呆在异界。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Wir können auf der Counterside nicht lange überleben."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Nous ne pouvons survivre longtemps dans le Contremonde."
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "EP5_ACT5_STAGE4_START@102#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 102
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 208
L2_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L2_1.m_Pos = "C"
L3_1 = "이터니움 실드 같은 장치를 쓴다고 해도 어차피 임시방편일 뿐이지......"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "エタニウムシールドのような装置を使うとしても、どうせその場しのぎでしかない。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Relying on devices like Eternium shields is just a temporary measure."
L2_1.m_Talk_ENG = L3_1
L3_1 = "使用永恆之金護盾也只是一時的權宜之計。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "การต้องพึ่งอุปกรณ์อย่างโล่อีเทอร์เนียมเป็นแค่มาตรการชั่วคราว"
L2_1.m_Talk_THA = L3_1
L3_1 = "Dựa vào các thiết bị như khiên Vàng Vĩnh Cửu chỉ là một biện pháp tạm thời."
L2_1.m_Talk_VTN = L3_1
L3_1 = "使用能晶盾牌也只是一时的权宜之计。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Geräte wie Eternium-Schilde helfen nur kurzfristig."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Les boucliers d'éternium ne sont qu'une mesure temporaire."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "EP5_ACT5_STAGE4_START@103#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 103
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 208
