L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L3_1.m_Pos = "C"
L4_1 = "시간이 지나면 인간은 결국 침식체로 붕괴해 버린다."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "時間が経てば、人間は結局、侵食体になってしまうのだ。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "As time passes, humans beings are bound to collapse into Corrupted Objects."
L3_1.m_Talk_ENG = L4_1
L4_1 = "隨著時間的流逝，人類終究會崩壞成侵蝕體。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "เมื่อเวลาผ่านไป มนุษย์ก็จะกลายเป็นวัตถุคอร์รัปต์"
L3_1.m_Talk_THA = L4_1
L4_1 = "Khi thời gian trôi qua, con người nhất định sẽ biến chất thành các Vật Thể Ăn Mòn."
L3_1.m_Talk_VTN = L4_1
L4_1 = "随着时间的流逝，人类最终会变成侵蚀体的。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Mit der Zeit werden Menschen trotzdem zwangsläufig zu Counterside-Objekten."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Plus le temps passe, plus les êtres humains sont voués à s'effondrer en objets corrompus."
L3_1.m_Talk_FRA = L4_1
