L5_1 = "그래서 나는 리플레이서 인자를 만들었다."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "だから、私はリプレイサーファクターを作った。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "That was why I created the Replacer Factor."
L4_1.m_Talk_ENG = L5_1
L5_1 = "所以我做出了克隆因子。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ด้วยเหตุนี้ ผมจึงสร้างรีเพลสเซอร์แฟกเตอร์ขึ้นมา"
L4_1.m_Talk_THA = L5_1
L5_1 = "Đó là lý do tại sao tôi tạo ra Nhân Tố Nhân Bản."
L4_1.m_Talk_VTN = L5_1
L5_1 = "所以我创造出了克隆因子。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Deshalb schuf ich den Replacer-Faktor."
L4_1.m_Talk_DEU = L5_1
L5_1 = "C'est pour cela que j'ai créé l'agent substituteur."
L4_1.m_Talk_FRA = L5_1
