L5_1.m_Pos = "C"
L6_1 = "역시 리플레이서 인자는 전투용이 아니었군요."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "やはりリプレイサーファクターは、戦闘のためではなかったのですね。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "So it was never meant to be used for combat."
L5_1.m_Talk_ENG = L6_1
L6_1 = "果然克隆因子不是用於戰鬥的。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "มันไม่ได้มีไว้เพื่อการต่อสู้ตั้งแต่แรก"
L5_1.m_Talk_THA = L6_1
L6_1 = "Tôi không bao giờ định sử dụng nó để chiến đấu."
L5_1.m_Talk_VTN = L6_1
L6_1 = "果然克隆因子不是用于战斗的。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Er war also nie für den Einsatz im Kampf gedacht."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Il n'a jamais été conçu pour être utilisé en combat."
L5_1.m_Talk_FRA = L6_1
