L6_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L6_1.m_Pos = "C"
L7_1 = "아마도 그 목적은...... 이면세계에서도 살아남을 수 있는 인간 변이체를 만드는 것."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "たぶんその目的は……裏世界でも生き残れる人間の変異体を作ること。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "It was a part of the plan to cause a mutation that would help mankind adjust to the environment of the Counterside."
L6_1.m_Talk_ENG = L7_1
L7_1 = "那個目的大概……是為了創造出可以在異界中活下來的人類變異體。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "มันเป็นส่วนหนึ่งของแผนในการสร้างการกลายพันธุ์ที่จะช่วยให้มนุษย์ปรับตัวให้เข้ากับสภาพแวดล้อมในเคาน์เตอร์ไซด์ได้"
L6_1.m_Talk_THA = L7_1
L7_1 = "Đó là một phần của kế hoạch để tạo ra đột biến giúp nhân loại thích nghi với môi trường của Counterside."
L6_1.m_Talk_VTN = L7_1
L7_1 = "大概目的是为了……创造出可以在异界中存活的人类变异体。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Sondern immer nur dazu, eine Mutation zu verursachen, durch die Menschen sich der Umwelt auf der Counterside anpassen würden."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Il faisait partie du plan pour provoquer une mutation susceptible d'aider l'humanité à s'adapter au Contremonde."
L6_1.m_Talk_FRA = L7_1
