L12_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L13_1 = "리플레이서 융합체는 안정적이지 못해."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "リプレイサー融合体は安定した存在ではなかったんだ。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Replacer hybriders weren't stable enough."
L12_1.m_Talk_ENG = L13_1
L13_1 = "克隆融合體無法保持穩定。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "รีเพลสเซอร์ประเภทไฮบริเดอร์ยังไม่เสถียรพอ"
L12_1.m_Talk_THA = L13_1
L13_1 = "Người Lai Tạo Nhân Bản không đủ ổn định."
L12_1.m_Talk_VTN = L13_1
L13_1 = "克隆融合体无法保持稳定。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Replacer-Hybride erwiesen sich als nicht stabil genug."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Les hybrides substituts n'étaient pas suffisamment stables."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "EP5_ACT5_STAGE4_START@113#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 113
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 208
L13_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L14_1 = "지속적으로 메인터넌스를 위한 리플레이서 인자를 추가 투여하지 않으면 결국 침식체나 다름없는 붕괴체로 바뀌어 버린다."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "メンテナンスのためのリプレイサーファクターを継続投与しないと、\n結局侵食体同然の崩壊体に変わってしまう。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "We had to provide them with Replacer Factors regularly, or they would turn into Collapsers, and Collapsers are barely better than C.O.s."
L13_1.m_Talk_ENG = L14_1
L14_1 = "如果不持續投入額外維護用的克隆因子，人類最終還是會變成侵蝕體或沒差多少的崩壞體。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "เราต้องป้อนรีเพลสเซอร์แฟกเตอร์เป็นประจำ ไม่งั้นพวกมันจะกลายเป็นคอแลปเซอร์ และคอแลปเซอร์ก็แทบจะไม่ได้ดีกว่าวัตถุคอร์รัปต์เลย"
L13_1.m_Talk_THA = L14_1
L14_1 = "Chúng tôi phải thường xuyên cung cấp cho họ các Nhân Tố Nhân Bản, nếu không họ sẽ biến thành Kẻ Phá Hủy và Kẻ Phá Hủy hầu như không tốt hơn V.T.B.A.M là bao."
L13_1.m_Talk_VTN = L14_1
L14_1 = "如果不持续投入用来维持稳定的克隆因子，人类最终还是会变成侵蚀体或其他的崩坏体。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Wir mussten sie regelmäßig mit Replacer-Faktoren versorgen, andernfalls wurden sie zu Zerborstenen, und Zerborstene sind fast so schlimm wie C. O.s."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Nous devions leur administrer de l'agent substituteur régulièrement, sous peine de les voir se transformer en anomalies. Et les anomalies valent à peine mieux que les O.C."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "EP5_ACT5_STAGE4_START@114#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 114
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 208
L14_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L15_1 = "안정적으로 융합 상태를 유지할 수 있는 얼터너티브 인자를 개발하긴 했지만......"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "安定的に融合状態を維持できるオルタナティブファクターの開発には成功したが……"
L14_1.m_Talk_JPN = L15_1
L15_1 = "We managed to develop the Alternative Factor, which guaranteed much better stability,"
L14_1.m_Talk_ENG = L15_1
L15_1 = "即使我們開發出了可以維持穩定融合狀態的可替代因子……"
L14_1.m_Talk_TWN = L15_1
L15_1 = "เราพัฒนาอัลเทอร์เนทีฟแฟกเตอร์ขึ้นมาได้ ซึ่งรับประกันความเสถียรมากกว่า"
L14_1.m_Talk_THA = L15_1
L15_1 = "Chúng tôi đã cố gắng phát triển Nhân Tố Nhân Bản để đảm bảo ổn định hơn,"
L14_1.m_Talk_VTN = L15_1
L15_1 = "虽然开发出了可以维持稳定融合状态的可替代因子……"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Es gelang uns zwar, den alternativen Faktor zu entwickeln, der tatsächlich mehr Stabilität brachte,"
L14_1.m_Talk_DEU = L15_1
L15_1 = "Nous avons réussi à développer l'agent alternatif, beaucoup plus stable,"
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "EP5_ACT5_STAGE4_START@115#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 115
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 208
L15_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L16_1 = "이건 카운터 능력자에게만 이식할 수 있는데다가...... 그나마 적성체 비율이 너무 낮아서 사실상 의미가 없었지."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "これはカウンター能力者にしか移植できない上に……\n適性体の確率が低すぎて、事実上、意味がなかった。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "but it could only be transplanted to a limited number of Counters who were physically receptive to it."
L15_1.m_Talk_ENG = L16_1
L16_1 = "但是這個只能移植於制裁者……而且就連適應體的比率也很低，幾乎沒有意義。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "แต่เราฝังมันให้เคาน์เตอร์ที่ร่างกายรับมันได้แค่จำนวนจำกัดเท่านั้น"
L15_1.m_Talk_THA = L16_1
L16_1 = "nhưng nó chỉ có thể được cấy vào một số ít các Counter có thể chất dễ dàng tiếp nhận nó."
L15_1.m_Talk_VTN = L16_1
L16_1 = "但是这个只能移植于制裁者……而且适应体的比率太低了，也基本没有希望。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "aber er ließ sich nur einer begrenzen Anzahl von Countern transplantieren, die körperlich auf ihn ansprachen."
L15_1.m_Talk_DEU = L16_1
L16_1 = "mais il ne pouvait être transplanté qu'à un nombre limité de Counters qui étaient physiquement capables de le recevoir."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "EP5_ACT5_STAGE4_START@116#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 116
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 208
L16_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L17_1 = "계속 연구를 진행했다면 어쩌면 더 범용적인 결과물을 만들어낼 수 있었을지도 모르지만......"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "研究を続けていれば、もしかしたら、より汎用的な結果を出せたかもしれないが……"
L16_1.m_Talk_JPN = L17_1
L17_1 = "If we had been able to continue our research, the end result could have been more appropriate for universal use,"
L16_1.m_Talk_ENG = L17_1
L17_1 = "如果我們繼續研究的話，應該可以製造出更為泛用的產物……"
L16_1.m_Talk_TWN = L17_1
L17_1 = "หากเราสามารถทำวิจัยต่อไป เราอาจได้ผลลัพธ์ที่เหมาะกับการใช้งานทั่วไปมากกว่านี้"
L16_1.m_Talk_THA = L17_1
L17_1 = "Nếu chúng tôi có thể tiếp tục nghiên cứu, thì kết quả cuối cùng có thể phù hợp hơn để sử dụng phổ biến,"
L16_1.m_Talk_VTN = L17_1
L17_1 = "虽然继续研究的话说不定会制造出更平庸的产物……"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Hätten wir unsere Forschung fortsetzen können, wäre das Endergebnis sicher besser für den allgemeinen Gebrauch geeignet gewesen,"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Si nous avions pu poursuivre nos recherches, le produit final aurait été bien plus adapté à un usage universel,"
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "EP5_ACT5_STAGE4_START@117#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 117
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 208
L17_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L18_1 = "유일한 이식 성공 실험체들이 모두 도망쳐 버린 터라 더 이상 연구를 지속할 수도 없었네."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "唯一、移植に成功した実験体がすべて逃げ出してしまったから、\nそれ以上研究を続けることもできなかった。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "but the subjects of our only successful transplant test had run away and we had nothing to work with."
L17_1.m_Talk_ENG = L18_1
L18_1 = "但是唯一移植成功的實驗體全都逃跑了，研究已經無法繼續了。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "แต่ตัวทดลองของการทดสอบฝังแฟกเตอร์ที่ประสบความสำเร็จของเราหนีไป และเราก็ไม่มีอะไรให้ทำงานต่อ"
L17_1.m_Talk_THA = L18_1
L18_1 = "nhưng các đối tượng của thử nghiệm cấy ghép thành công duy nhất của chúng tôi đã bỏ chạy và chúng tôi không còn gì để làm việc."
L17_1.m_Talk_VTN = L18_1
L18_1 = "但是唯一移植成功的试验体都逃跑了，研究也无法继续了。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "aber die Versuchspersonen der einzig erfolgreichen Einpflanzung flohen und wir hatten nichts, womit wir arbeiten konnten."
L17_1.m_Talk_DEU = L18_1
L18_1 = "mais les sujets de notre seule transplantation réussie se sont enfuis et nous n'avions plus rien sur quoi travailler."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "EP5_ACT5_STAGE4_START@118#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 118
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 208
L18_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L19_1 = "성공 실험체라면...... 서윤과 알트소대를 말하는 건가?"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "成功した実験体って……シズカとアルト小隊のこと？"
L18_1.m_Talk_JPN = L19_1
L19_1 = "By subjects, do you mean Seo Yoon and the ALT Squad?"
L18_1.m_Talk_ENG = L19_1
L19_1 = "成功的實驗體……你是說徐芸和阿爾特小隊嗎？"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ตัวทดลองที่ว่านี้คุณหมายถึงซอ ยุนกับหน่วย ALT ใช่ไหม?"
L18_1.m_Talk_THA = L19_1
L19_1 = "Nói đến đối tượng, ý bạn là Seo Yoon và Tiểu Đội ALT ư?"
L18_1.m_Talk_VTN = L19_1
L19_1 = "成功的试验体……是说徐芸和阿尔特小队吗？"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Mit Versuchspersonen meinst du Seo Yoon und den ALT-Trupp?"
L18_1.m_Talk_DEU = L19_1
L19_1 = "Quand vous dites sujets, vous parlez de Seo Yoon et de l'escouade ALT ?"
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "EP5_ACT5_STAGE4_START@119#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 119
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 208
L19_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L20_1 = "그래, 그 아이들이지. 우리가 그 아이들을 계속 찾았던 이유이기도 하고."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "そうだ。だからこそ、我々はその子たちを探していた。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Yes. That's why we were looking everywhere for them."
L19_1.m_Talk_ENG = L20_1
L20_1 = "沒錯，就是那些孩子。這就是我們一直在找那些孩子的理由。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ใช่ ดังนั้นเราถึงตามหาพวกเขาไปทั่ว"
L19_1.m_Talk_THA = L20_1
L20_1 = "Đúng. Đó là lý do tại sao chúng tôi đã tìm kiếm họ ở khắp mọi nơi."
L19_1.m_Talk_VTN = L20_1
L20_1 = "没错，就是那些孩子们。所以我们一直在找那些孩子们。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Ja. Deshalb haben wir überall nach ihnen gesucht."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Oui. C'est la raison pour laquelle nous les avons cherchées partout."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
