L24_1 = "EP5_ACT5_STAGE4_START@123#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 123
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 208
L23_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_Face = "UNIT_IDLE"
L23_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L23_1.m_Pos = "C"
L24_1 = "하지만 더 이상 그럴 필요가 없어졌네. 왜냐하면 자네가 나타났기 때문이지."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "だが、もうそんな必要はない。なぜなら、君が現れたからな。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "But then it was no longer necessary, because we found you."
L23_1.m_Talk_ENG = L24_1
L24_1 = "但是已經沒必要繼續找了。因為妳出現了。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "แต่มันก็ไม่จำเป็นแล้วละ เพราะเราพบคุณแล้ว"
L23_1.m_Talk_THA = L24_1
L24_1 = "Nhưng rồi điều đó không còn cần thiết nữa, vì chúng tôi đã tìm thấy bạn."
L23_1.m_Talk_VTN = L24_1
L24_1 = "但是没必要继续找了。因为你们出现了。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Aber dann war das nicht mehr nötig, denn wir fanden dich:"
L23_1.m_Talk_DEU = L24_1
L24_1 = "Puis c'est devenu inutile, car nous vous avons trouvée."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
