L28_1 = "그래. 종말의 씨앗, 진정한 초월 변이인자의 블루프린트."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "そうだ。終末の種であり、真の超越変異ファクターの設計図。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Yes. The seed of apocalypse, the blueprint of the true Transcendental Mutation Factor..."
L27_1.m_Talk_ENG = L28_1
L28_1 = "沒錯。末日的種子，真正超越變異因子的藍圖。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ใช่ เมล็ดพันธุ์ของวันสิ้นโลก พิมพ์เขียวของมิวเทชั่นแฟกเตอร์ที่ยอดเยี่ยมอย่างแท้จริง"
L27_1.m_Talk_THA = L28_1
L28_1 = "Đúng. Hạt giống ngày tận thế, bản thiết kế của Nhân Tố Đột Biến siêu việt thực sự..."
L27_1.m_Talk_VTN = L28_1
L28_1 = "没错。末日的种子，真的超越变异因子的蓝图。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Ja. Den Samen der Apokalypse, die Blaupause des Transzendentalen Mutationsfaktors …"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Oui. La graine de l'apocalypse, le modèle du véritable agent transcendantal de mutation..."
L27_1.m_Talk_FRA = L28_1
