L32_1.m_Pos = "L"
L33_1 = "잃어버린 얼터너티브 인자의 개량 대신 클리포트 인자를 복제하기로 했군요."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "失ったオルタナティブ・ファクターの改良の代わりに、\nクリフォト・ファクターを複製することに決めたんですね。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "You decided to copy the Qliphoth Factors rather than improving the lost Alternative Factors."
L32_1.m_Talk_ENG = L33_1
L33_1 = "你們沒有改良遺失的可替代因子，而是選擇複製逆卡巴拉因子了吧。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "คุณตัดสินใจคัดลอกคลิฟอธแฟกเตอร์แทนที่จะพัฒนาอัลเทอร์เนทีฟแฟกเตอร์ที่หายไป"
L32_1.m_Talk_THA = L33_1
L33_1 = "Bạn đã quyết định sao chép Nhân Tố Qliphoth thay vì cải tiến Nhân Tố Qliphoth đã mất."
L32_1.m_Talk_VTN = L33_1
L33_1 = "为了取代对遗失的可替代因子的改良，你们决定开始复制神圣因子了啊。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "… beschlossen Sie, die Klippot-Faktoren zu kopieren, statt die verlorenen alternativen Faktoren zu verbessern."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Vous avez décidé de copier les agents qliphoth plutôt que de chercher à améliorer les agents alternatifs disparus."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
