L35_1 = "EP5_ACT5_STAGE4_START@134#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 134
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 208
L34_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L34_1.m_Pos = "C"
L35_1 = "그래. 리플레이서 인자는 원래 북극점 공방전에 등장한 제 5종 침식체,"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "そのとおりだ。リプレイサーファクターは元々北極点攻防戦に登場した、第5種侵食体。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Yes. The Replacer Factor is actually an imitation of the core Eternium we found from the Nameless One,"
L34_1.m_Talk_ENG = L35_1
L35_1 = "沒錯。克隆因子本來就是模仿北極點攻防戰中，登場的第5級侵蝕體——"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ใช่ รีเพลสเซอร์แฟกเตอร์คือการจำลองอีเทอร์เนียมหลักที่เราพบในผู้ไร้นาม"
L34_1.m_Talk_THA = L35_1
L35_1 = "Đúng. Nhân Tố Nhân Bản thực sự là cái bắt chước Vàng Vĩnh Cửu lõi mà chúng tôi tìm thấy từ Kẻ Vô Danh"
L34_1.m_Talk_VTN = L35_1
L35_1 = "没错。克隆因子本来是模仿在北极点防空战中出现的5级侵蚀体，"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Ja. Beim Replacer-Faktor handelt es sich im Grunde genommen um nachgemachtes Kern-Eternium, das wir im Namenlosen gefunden haben,"
L34_1.m_Talk_DEU = L35_1
L35_1 = "Oui. L'agent substituteur est en réalité une imitation du noyau d'éternium que nous avons trouvé sur le Sans Nom,"
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "EP5_ACT5_STAGE4_START@135#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 135
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 208
L35_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L35_1.m_Pos = "C"
L36_1 = "네임리스 원의 코어 이터니움을 모방하여 만들어낸 거다."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "ネームレスワンのコアエタニウムを真似て作りだしたものだ。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "the Category 5 C.O. that appeared during the North Pole Battle."
L35_1.m_Talk_ENG = L36_1
L36_1 = "無名1的核心永恆之金做出來的"
L35_1.m_Talk_TWN = L36_1
L36_1 = "วัตถุคอร์รัปต์คลาส 5 ที่ปรากฏขึ้นในสงครามขั้วโลกเหนือ"
L35_1.m_Talk_THA = L36_1
L36_1 = "V.T.B.A.M Hạng 5 đã xuất hiện trong Trận Chiến Bắc Cực."
L35_1.m_Talk_VTN = L36_1
L36_1 = "无名体的核心能晶制造出来的。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "jenem C. O. der Kategorie 5, das während der Nordpol-Schlacht auftauchte."
L35_1.m_Talk_DEU = L36_1
L36_1 = "l'objet corrompu catégorie 5 qui est apparu durant la Bataille du pôle Nord."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "EP5_ACT5_STAGE4_START@136#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 136
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 208
L36_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L36_1.m_Pos = "C"
L37_1 = "유실된 부분이 많기 때문에 열화 복제품인 리플레이서 인자로는 원본 코어 구조를 완전히 재현해낼 수 없었지만,"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "欠けている部分が多く、劣化版のレプリカであるリプレイサーファクターでは、\n原本のコア構造の完全再現はできなかったが、"
L36_1.m_Talk_JPN = L37_1
L37_1 = "The core had already been disfigured when we started out, and being the crude copy that it was, the Replacer Factors couldn't be used to reproduce the structure of the original core."
L36_1.m_Talk_ENG = L37_1
L37_1 = "雖然因為遺失的部分太多，作為劣化複製品的克隆因子無法完全再現原本的核心構造……"
L36_1.m_Talk_TWN = L37_1
L37_1 = "แกนนั้นได้รับความเสียหายแล้วตอนที่เราเริ่มทดลอง แต่การที่มันเป็นแค่แบบจำลองหยาบๆ ทำให้เราไม่สามารถใช้รีเพลสเซอร์แฟกเตอร์ในการผลิตโครงสร้างของแกนดั้งเดิมได้"
L36_1.m_Talk_THA = L37_1
L37_1 = "Lõi đã bị biến dạng khi chúng tôi bắt đầu và vì là bản sao thô của nó, các Nhân Tố Nhân Bản không thể được sử dụng để tái tạo cấu trúc của lõi ban đầu."
L36_1.m_Talk_VTN = L37_1
L37_1 = "虽然因为遗失的部分太多，热化学复制品克隆因子无法完全再现本体的核心构造，"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Der Kern hatte sich schon zu Beginn verformt, und die Replacer-Faktoren waren obendrein nur grobe Kopien. Sie konnten die Struktur des ursprünglichen Kerns nicht nachbilden."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Le noyau était déjà en mauvais état lorsque nous avons commencé et l'agent substituteur, en simple copie grossière, était incapable de reproduire la structure du noyau originel."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "EP5_ACT5_STAGE4_START@137#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 208
L37_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L37_1.m_Pos = "C"
L38_1 = "결손된 구조를 클리포트 인자로 대체한다면......"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "一部欠けている部分をクリフォト・ファクターで代替することができれば……"
L37_1.m_Talk_JPN = L38_1
L38_1 = "But if we could use Qliphoth Factors to plug all the holes,"
L37_1.m_Talk_ENG = L38_1
L38_1 = "但缺損的部分如果用逆卡巴拉因子替代的話……"
L37_1.m_Talk_TWN = L38_1
L38_1 = "แต่ถ้าเราใช้คลิฟอธแฟกเตอร์อุดรูทั้งหมดได้"
L37_1.m_Talk_THA = L38_1
L38_1 = "Nhưng nếu chúng ta có thể sử dụng Nhân Tố Qliphoth để cắm vào tất cả các lỗ,"
L37_1.m_Talk_VTN = L38_1
L38_1 = "但是缺损的部分由神圣因子替代的话……"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Wenn wir jedoch in der Lage wären, all diese Löcher mit Klippot-Faktoren zu stopfen,"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Mais avec l'apport des agents qliphoth pour combler les brèches,"
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "EP5_ACT5_STAGE4_START@138#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 138
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 208
L38_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L38_1.m_Pos = "C"
L39_1 = "인간을...... 네임리스 원과 같은 제 5종 침식체로 진화시킬 수 있게 된다."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "人間を……ネームレスワン同然の第5種侵食体に進化させることができる。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "we'd be able to turn a human into a Category 5 C.O. like the Nameless One."
L38_1.m_Talk_ENG = L39_1
