L38_1.m_Talk_TWN = L39_1
L39_1 = "เราก็จะเปลี่ยนมนุษย์ให้เป็นวัตถุคอร์รัปต์คลาส 5 แบบผู้ไร้นามได้"
L38_1.m_Talk_THA = L39_1
L39_1 = "chúng ta có thể biến con người thành V.T.B.A.M Hạng 5 giống như Kẻ Không Tên."
L38_1.m_Talk_VTN = L39_1
L39_1 = "可以让人类进化成……5级侵蚀体。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "könnten wir Menschen in C. O.s der Kategorie 5 wie den Namenlosen verwandeln."
L38_1.m_Talk_DEU = L39_1
L39_1 = "nous étions enfin en mesure de transformer un humain en O.C. catégorie 5 comme le Sans Nom."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
