L41_1 = "그게 무슨 소리야?! 인간이 침식체로 붕괴하는 걸 막기 위해 리플레이서 인자를 만들었다면서?"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "どういうこと！？　人間が侵食体になるのを防ぐために、リプレイサーファクターを作ったんでしょ？"
L40_1.m_Talk_JPN = L41_1
L41_1 = "You're talking nonsense! You just said you created the Replacer Factor to keep humans from collapsing into C.O.s,"
L40_1.m_Talk_ENG = L41_1
L41_1 = "這是什麼意思？！你不是是為了阻止人類崩壞成侵蝕體，才做出的克隆因子嗎？"
L40_1.m_Talk_TWN = L41_1
L41_1 = "คุณพูดจาเหลวไหลแล้วละ! คุณเพิ่งบอกว่าคุณสร้างรีเพลสเซอร์แฟกเตอร์เพื่อป้องกันไม่ให้มนุษย์กลายเป็นวัตถุคอร์รัปต์"
L40_1.m_Talk_THA = L41_1
L41_1 = "Bạn thật mâu thuẫn! Bạn vừa nói rằng bạn đã tạo ra Nhân Tố Nhân Bản để giúp con người không bị biến thành V.T.B.A.M,"
L40_1.m_Talk_VTN = L41_1
L41_1 = "你是什么意思啊？！不是说是为了阻止人类崩溃成侵蚀体才创造的克隆因子吗？"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Das ist doch ein Widerspruch! Gerade hast du noch gesagt, du hast den Replacer-Faktor geschaffen, damit Menschen nicht zu C. O.s werden,"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Ça n'a aucun sens ! Vous venez de dire que vous aviez créé l'agent substituteur pour empêcher les humains de se transformer en O.C.,"
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
