L42_1 = 40
L41_1.m_Crash = L42_1
L42_1 = "그런데 인간을 다시 5종 침식체로 진화시킨다니...... 앞뒤가 안 맞잖아?!"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "なのに、人間を第5種侵食体に進化させるなんて……矛盾してるじゃない！？"
L41_1.m_Talk_JPN = L42_1
L42_1 = "and now you're talking about evolving humans into Category 5 C.O.s. That doesn't make any sense!"
L41_1.m_Talk_ENG = L42_1
L42_1 = "但怎麼又要把人類進化成第5級侵蝕體……你這不是前後矛盾嗎？！"
L41_1.m_Talk_TWN = L42_1
L42_1 = "แล้วตอนนี้คุณมาพูดถึงการพัฒนามนุษย์ให้กลายเป็นวัตถุคอร์รัปต์คลาส 5 ฟังดูไม่สมเหตุสมผลเลย!"
L41_1.m_Talk_THA = L42_1
L42_1 = "và bây giờ bạn đang nói về việc tiến hóa con người thành V.T.B.A.M Hạng 5. Điều đó thật vô lý!"
L41_1.m_Talk_VTN = L42_1
L42_1 = "怎么又说要把人类进化成5级侵蚀体啊……你前后矛盾了啊？！"
L41_1.m_Talk_SCN = L42_1
L42_1 = "und jetzt redest du davon, Menschen zu C. O.s der Kategorie 5 zu machen! Das ergibt doch keinen Sinn!"
L41_1.m_Talk_DEU = L42_1
L42_1 = "et maintenant vous voulez les transformer en O.C. catégorie 5 ? Ça ne rime à rien !"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "EP5_ACT5_STAGE4_START@142#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 142
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 208
L42_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L42_1.m_bWaitClick = true
