L42_1.m_Face = "UNIT_IDLE"
L42_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L42_1.m_Pos = "C"
L43_1 = "제 5종 침식체 네임리스 원은 일반적인 침식체와 다르다."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "第5種侵食体のネームレスワンは、通常の侵食体とは別物だ。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "The Nameless One, or the Category 5 C.O., is different from regular C.O.s."
L42_1.m_Talk_ENG = L43_1
L43_1 = "第5級侵蝕體無名1和一般的侵蝕體不一樣。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ผู้ไร้นามหรือวัตถุคอร์รัปต์คลาส 5 แตกต่างจากวัตถุคอร์รัปต์ทั่วไป"
L42_1.m_Talk_THA = L43_1
L43_1 = "Kẻ Vô Danh, hay V.T.B.A.M Hạng 5, khác với V.T.B.A.M thông thường."
L42_1.m_Talk_VTN = L43_1
L43_1 = "5级侵蚀体和一般的侵蚀体不一样。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Doch. Weil der Namenlose, oder das C. O. der Kategorie 5, anders ist als andere C. O.s."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Le Sans Nom, ou l'O.C. catégorie 5 si vous préférez, est différent des objets corrompus ordinaires."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "EP5_ACT5_STAGE4_START@143#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 143
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 208
L43_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L43_1.m_Pos = "C"
L44_1 = "이성을 유지할 수도 있고, 침식 광기에 대한 내성도 어느 정도 기대할 수 있어."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "理性を保つこともできるし、侵食による狂気への耐性もある程度は期待できる。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "It's quite resistant to Corruption Frenzy, and does not lose its ability to reason."
L43_1.m_Talk_ENG = L44_1
L44_1 = "第5級侵蝕體可以保持理性，也可以期待它能對侵蝕發狂一定程度的耐性。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "มันค่อนข้างทนทานต่อกระแสคอร์รัปชั่น และไม่สูญเสียความสามารถในการใช้เหตุผล"
L43_1.m_Talk_THA = L44_1
L44_1 = "Nó có khả năng chống Đóng Băng Ăn Mòn khá tốt và không bị mất khả năng tư duy."
L43_1.m_Talk_VTN = L44_1
L44_1 = "5级侵蚀体可以保持理性，对侵蚀狂症还有一定的自我控制。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Er ist ziemlich resistent gegen Verderbnis-Raserei und verliert nicht seine Vernunftbegabung."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Il est plutôt résistant à la frénésie de corruption, et ne perd pas ses facultés à raisonner."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "EP5_ACT5_STAGE4_START@144#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 144
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 208
L44_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L44_1.m_Pos = "C"
L45_1 = "충분하지는 않더라도 인류와 인류 문명을 존속시킨다는 목표는 달성할 수 있겠지."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "十分ではなくとも、人類や人類の文明を存続させるという目標は達成できるだろう。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "I don't believe it's a cure-all, but it'd be enough to let us achieve our goal and keep humanity and its civilization going."
L44_1.m_Talk_ENG = L45_1
L45_1 = "就算不夠完全，也可以達成人類和人類文明存續下去的目的。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ผมไม่เชื่อว่ามันแก้ปัญหาได้ทุกอย่าง แต่แค่นี้ก็มากพอแล้วที่จะทำให้เราบรรลุเป้าหมาย และทำให้มนุษยชาติและอารยธรรมคงอยู่ต่อไปได้"
L44_1.m_Talk_THA = L45_1
L45_1 = "Tôi không tin rằng đó là một phương pháp chữa trị hoàn hảo, nhưng nó đủ để chúng ta đạt được mục tiêu của mình và giữ cho nhân loại và nền văn minh của chúng ta tiếp tục phát triển."
L44_1.m_Talk_VTN = L45_1
L45_1 = "虽然还不完全，但可以使人类和人类文明存续下去。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Ich halte es auch nicht für das Allheilmittel, aber es reicht, um unser Ziel zu erreichen und die Menschheit und die Zivilisation zu retten."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Je ne dis pas qu'il s'agit d'un remède miracle, mais il sera suffisant pour nous permettre d'atteindre notre objectif et faire perdurer la civilisation humaine."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "EP5_ACT5_STAGE4_START@145#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 145
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 208
L45_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L45_1.m_Pos = "C"
L46_1 = "그리고 무엇보다도...... 이것이 종말이 도래하기 전에 시도해 볼 수 있는 유일한 방법이니까."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "そして何より……これは終末が訪れる前に試せる、唯一の方法なんだ。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "And more than anything, this is the last thing we can try before the end comes."
L45_1.m_Talk_ENG = L46_1
L46_1 = "而且最重要的……這是末日到來之前，可以嘗試的唯一辦法了。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "และที่สำคัญที่สุด นี่เป็นสิ่งสุดท้ายที่เราทำได้ ก่อนที่จุดจบจะมาถึง"
L45_1.m_Talk_THA = L46_1
L46_1 = "Và hơn bất cứ điều gì, đây là điều cuối cùng mà chúng ta có thể thử trước khi ngày tàn đến."
L45_1.m_Talk_VTN = L46_1
L46_1 = "而且不管怎么说……这是末日到来之前唯一可以试试看的办法了。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Vor allen Dingen aber haben wir keine Alternativen mehr."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Et surtout, c'est la dernière chose que nous pouvons essayer avant la fin du monde."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "EP5_ACT5_STAGE4_START@146#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 146
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 208
