L46_1.m_Pos = "C"
L47_1 = "......설명이 하나 빠진 것 같네요."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "……一つ、説明が抜けているようですね。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "You're leaving out an important part."
L46_1.m_Talk_ENG = L47_1
L47_1 = "……你有一件事沒有解釋呢。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "คุณข้ามส่วนสำคัญไปนะ"
L46_1.m_Talk_THA = L47_1
L47_1 = "Bạn đang bỏ qua một phần quan trọng."
L46_1.m_Talk_VTN = L47_1
L47_1 = "……还有一个要告诉你们。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Du lässt da nur einen wichtigen Teil weg."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Vous omettez une donnée importante."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
