L47_1.m_fWaitTime = 0
L47_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L47_1.m_Pos = "C"
L48_1 = "인간을 제 5종 침식체로 진화시킨다고 해도...... 그게 모든 인간은 아니겠죠?"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "人間を第5種侵食体に進化させるにしても……対象はすべての人間ではないですよね？"
L47_1.m_Talk_JPN = L48_1
L48_1 = "You said you're going to evolve humans into Category 5 C.O.s, but you're not talking about all humans, are you?"
L47_1.m_Talk_ENG = L48_1
L48_1 = "就算人類能進化成第5級侵蝕體……那也不是所有人類吧？"
L47_1.m_Talk_TWN = L48_1
L48_1 = "คุณบอกว่าคุณจะพัฒนามนุษย์ให้่กลายเป็นวัตถุคอร์รัปต์คลาส 5 แต่คุณไม่ได้พูดถึงมนุษย์ทุกคนใช่ไหม?"
L47_1.m_Talk_THA = L48_1
L48_1 = "Bạn nói rằng bạn sẽ tiến hóa loài người thành V.T.B.A.M Hạng 5, nhưng bạn không nói về tất cả con người, phải không?"
L47_1.m_Talk_VTN = L48_1
L48_1 = "就算人类进化成5级侵蚀体……那也不是人类了吧？"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Du redest davon, Menschen in C. O.s der Kategorie 5 zu verwandeln, aber du meinst nicht alle Menschen, oder?"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Vous disiez vouloir faire évoluer les humains en O.C. catégorie 5, mais j'imagine que vous ne parlez pas de tous les humains, n'est-ce pas ?"
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "EP5_ACT5_STAGE4_START@148#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 148
