L48_1.m_Pos = "C"
L49_1 = "대체 몇 명이나 살려서 이면세계로 데려가실 생각이시죠?"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "いったいどれだけの数を生かして、裏世界へ連れていくつもりですか？"
L48_1.m_Talk_JPN = L49_1
L49_1 = "How many are you planning to take to the Counterside?"
L48_1.m_Talk_ENG = L49_1
L49_1 = "你到底打算救幾個人，把他們帶進異界去呢？"
L48_1.m_Talk_TWN = L49_1
L49_1 = "คุณวางแผนจะพามนุษย์กี่คนเข้ามาในเคาน์เตอร์ไซด์?"
L48_1.m_Talk_THA = L49_1
L49_1 = "Bạn dự định đưa bao nhiêu người đến Counterside?"
L48_1.m_Talk_VTN = L49_1
L49_1 = "你到底救了几个人，想把他们带进异界呢？"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Wie viele wollen Sie auf die Counterside mitnehmen?"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Combien d'entre eux avez-vous l'intention d'emmener dans le Contremonde ?"
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
