L51_1 = "클리포트 레플리카 인자의 융합 적성체 비율은 그다지 높진 않다."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "レプリカ・クリフォト・ファクターの融合適性体の確率はそこまで高くない。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "There are only a small number of people who have enough receptivity to Qliphoth Replica Factors."
L50_1.m_Talk_ENG = L51_1
L51_1 = "逆卡巴拉複製因子的融合適應體比率不是很高。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "คนที่ร่างกายยอมรับคลิฟอธแฟกเตอร์จำลองได้มีแค่ไม่กี่คนเท่านั้น"
L50_1.m_Talk_THA = L51_1
L51_1 = "Chỉ có một số ít người có đủ khả năng tiếp nhận các Nhân Tố Nhân Bản Qliphoth."
L50_1.m_Talk_VTN = L51_1
L51_1 = "神圣复制因子的融合适应体比率不高。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Nur eine geringe Anzahl von Menschen spricht im ausreichenden Maße auf die nachgemachten Klippot-Faktoren an."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Il n'y a qu'un petit nombre de personnes suffisamment réceptives aux répliques d'agent qliphoth."
L50_1.m_Talk_FRA = L51_1
