L1_1.m_Pos = "C"
L2_1 = "낙관적으로 잡는다면 10%...... 보수적으로 잡는다면 5% 정도라고 예측하고 있네."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "甘く見積もって10％……現実的に考えると、5％程度を想定している。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Approximately 10%, and more like 5% if I'm being conservative."
L1_1.m_Talk_ENG = L2_1
L2_1 = "樂觀來看有10%……保守來看只有5%。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ประมาณ 10% และน่าจะแค่ 5% ถ้าจะให้ผมพูดแบบระมัดระวังนะ"
L1_1.m_Talk_THA = L2_1
L2_1 = "Khoảng 10%, và hơn 5%, đó là tôi khiêm tốn nói vậy."
L1_1.m_Talk_VTN = L2_1
L2_1 = "乐观的来说有10%……保守预测的话只有5%。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Etwa 10 %, nach konservativer Rechnung sogar eher nur 5 %."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Environ 10 %, et même plutôt 5 % en étant prudent."
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "EP5_ACT5_STAGE4_START@152#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 152
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 208
