L4_1 = "EP5_ACT5_STAGE4_START@153#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 153
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 208
L3_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L3_1.m_Pos = "C"
L4_1 = "메인터넌스용 리플레이서 인자 정도는 지금처럼 붕괴체들을 생체공장으로 활용하여 조달할 수 있겠지만......"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "メンテナンス用のリプレイサーファクターぐらいは、\n今のように崩壊体を生体工場として活用すれば調達できるでしょうけど……"
L3_1.m_Talk_JPN = L4_1
L4_1 = "You could secure enough supply of maintenance-purpose Replacer Factors using the collapsers as factories,"
L3_1.m_Talk_ENG = L4_1
L4_1 = "維護用的克隆因子，雖然可以像現在這樣，把崩壞體帶進活體工廠來獲得……"
L3_1.m_Talk_TWN = L4_1
L4_1 = "คุณอาจหาเสบียงได้มากพอที่จะบำรุงรักษารีเพลสเซอร์แฟกเตอร์โดยใช้คอแลปเซอร์เป็นโรงงานได้"
L3_1.m_Talk_THA = L4_1
L4_1 = "Bạn có thể đảm bảo cung cấp đủ các Nhân Tố Nhân Bản cho mục đích duy trì bằng cách sử dụng kẻ phá hủy như các xưởng sản xuất,"
L3_1.m_Talk_VTN = L4_1
L4_1 = "虽然像现在这样，把崩坏体带进活体工厂可以筹集到足够的维稳用克隆因子……"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Wenn du die Zerborstenen als Produktionsstätten verwendest, hättest du zwar genügend Nachschub zu Wartungszwecken,"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Vous pouvez vous assurer un approvisionnement suffisant en agent substituteur de maintenance en drainant les anomalies,"
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
