L5_1 = "클리포트 레플리카 인자를 생산하려면...... 그 정도로는 부족할 텐데요?"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "レプリカ・クリフォト・ファクターを生産するには……それだけじゃ足りないのでは？"
L4_1.m_Talk_JPN = L5_1
L5_1 = "but maintaining steady production of Qliphoth Replica Factors is a completely different story."
L4_1.m_Talk_ENG = L5_1
L5_1 = "但是想要生產逆卡巴拉複製因子……這還是不夠的吧？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "แต่การรักษาระดับการผลิตคลิฟอธแฟกเตอร์จำลองอย่างต่อเนื่องนี่เป็นอีกเรื่องหนึ่งเลยนะ"
L4_1.m_Talk_THA = L5_1
L5_1 = "nhưng việc duy trì sản xuất đều đặn Nhân Tố Bản Sao Qliquoth lại là một câu chuyện hoàn toàn khác."
L4_1.m_Talk_VTN = L5_1
L5_1 = "但是想要生产神圣复制因子……这还是不够的吧？"
L4_1.m_Talk_SCN = L5_1
L5_1 = "aber die ständige Produktion von nachgemachten Klippot-Faktoren stünde immer noch auf einem anderen Blatt."
L4_1.m_Talk_DEU = L5_1
L5_1 = "mais soutenir une production régulière de répliques d'agent qliphoth est une tout autre histoire."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
