L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 157
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 208
L7_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
