L7_1.m_Pos = "C"
L8_1 = "충분한 수율을 유지하려면 좀 더 극단적인 방법이 필요하지."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "十分な収率を保つためには、もっと極端な方法が必要だ。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "We'll have to resort to a rather extreme measure to produce enough for everyone."
L7_1.m_Talk_ENG = L8_1
L8_1 = "想要維持足夠的產量，就必須使用更加極端的方法。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "เราจะต้องหันไปใช้มาตรการที่สุดขั้วกว่านี้ในการผลิตให้มากพอสำหรับทุกคน"
L7_1.m_Talk_THA = L8_1
L8_1 = "Chúng ta sẽ phải dùng đến một biện pháp khá cực đoan để sản xuất đủ cho mọi người."
L7_1.m_Talk_VTN = L8_1
L8_1 = "想要维持高的收益率，还需要更加极端的办法。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Um genügend für alle herzustellen, müssten wir zu extremen Mitteln greifen."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Nous allons devoir recourir à une mesure plutôt extrême pour pouvoir en produire suffisamment pour tout le monde."
L7_1.m_Talk_FRA = L8_1
