L12_1 = "......대략 예상이 가는군요."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "……だいたい予想はつきますね。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "I think I know what it is."
L11_1.m_Talk_ENG = L12_1
L12_1 = "……我大概能猜到了。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ผมว่าผมเข้าใจแล้วละ"
L11_1.m_Talk_THA = L12_1
L12_1 = "Tôi nghĩ tôi biết nó là gì rồi."
L11_1.m_Talk_VTN = L12_1
L12_1 = "……大概可以预想到。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Ich kann mir vorstellen, was damit gemeint ist."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Je crois savoir de quoi il s'agit."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "EP5_ACT5_STAGE4_START@162#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 162
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 208
L12_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L12_1.m_Pos = "L"
L13_1 = "미나 양. 여긴 리플레이서 총기함 뉴 오하이오입니다."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "ミナさん。ここは、リプレイサー総旗艦のニューオハイオです。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Mina, this is the New Ohio, the flagship of the Replacer Syndicate."
L12_1.m_Talk_ENG = L13_1
L13_1 = "米娜小姐。這裡是克隆集團的武裝艦船新俄亥俄。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "มีนา นี่คือนิวโอไฮโอ ยานรบหลักของรีเพลสเซอร์ซินดิเคต"
L12_1.m_Talk_THA = L13_1
L13_1 = "Mina, đây là Tân Ohio, lá cờ đầu của Nghiệp Đoàn Nhân Bản."
L12_1.m_Talk_VTN = L13_1
L13_1 = "米娜小姐。这是克隆集团的武装舰船伊欧。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Mina, dies ist die New Ohio, das Flaggschiff des Replacer-Syndikats."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Mina, nous sommes dans le New Ohio, le vaisseau amiral du Syndicat des substituts."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "EP5_ACT5_STAGE4_START@163#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 163
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 208
L13_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L13_1.m_Pos = "L"
L14_1 = "주력 부대가 관리국 함대를 상대하러 갔다고 해도 기함 내에 방어병력이 전혀 없다는 건 아무래도 부자연스럽죠."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "主力部隊が管理局の艦隊の相手をしてるにしても、\n旗艦のなかに防御部隊がまったくいないのは、不自然なことです。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Their main forces may have left to fight the Administration fleet, but it makes no sense that they didn't leave a single guard here to defend their flagship."
L13_1.m_Talk_ENG = L14_1
L14_1 = "就算克隆集團的主力部隊去對付管理局的艦隊了，但司令艦內部完全沒有防禦兵力也太不合理了。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "กองกำลังหลักของพวกมันอาจต้องต่อสู้กับกองกำลังขององค์การบริหารโลก แต่การที่ไม่มีใครคุมที่นี่เพื่อป้องกันยานรบหลักเลยมันไม่สมเหตุสมผล"
L13_1.m_Talk_THA = L14_1
L14_1 = "Lực lượng chính của họ có thể đã rời đi để chiến đấu với hạm đội của Cục Quản Lý, nhưng thật vô lý khi họ không để lại một lính canh nào ở đây để bảo vệ soái hạm của họ."
L13_1.m_Talk_VTN = L14_1
L14_1 = "就算它的主力部队去对付管理局的舰队了，司令舰内部也不可能完全没有防御兵力。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Seine Hauptstreitmacht kämpft vielleicht gegen die Flotte der Administration, aber es ergibt keinen Sinn, dass sie das Flaggschiff vollkommen unbewacht zurückgelassen haben."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Leurs forces principales sont peut-être sorties combattre la flotte de l'Administration, mais il est illogique de ne trouver aucun garde ici pour défendre leur vaisseau amiral."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "EP5_ACT5_STAGE4_START@164#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 164
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 208
L14_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L14_1.m_Pos = "L"
L15_1 = "제 생각에는...... 이곳에 모여 있던 리플레이서 병력들은 모두 클리포트 레플리카 인자 제작을 위한 재료로 사용되었을 겁니다."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "僕が思うに……ここにいたリプレイサー兵の全てが、\nレプリカ・クリフォト・ファクターを作るための材料になったのでしょう。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "My guess is, all the Replacers that were here were used as material for Qliphoth Replica Factors."
L14_1.m_Talk_ENG = L15_1
L15_1 = "我想……在這裡的克隆集團兵力，應該全部被當成製造逆卡巴拉複製因子的材料了。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ผมเดาว่ารีเพลสเซอร์ทั้งหมดที่อยู่ที่นี่ถูกใช้เป็นวัสดุสำหรับการทำคลิฟอธแฟกเตอร์จำลองหมดแล้ว"
L14_1.m_Talk_THA = L15_1
L15_1 = "Tôi đoán là, tất cả Người Nhân Bản ở đây đã được sử dụng làm vật liệu cho Nhân Tố Nhân Bản Qliphoth."
L14_1.m_Talk_VTN = L15_1
L15_1 = "我觉得……这里的克隆集团兵力估计是全部被用去制造神圣复制因子了。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Ich vermute daher, dass alle Replacer, die hier waren, als Rohmaterial für nachgemachte Klippot-Faktoren verwendet wurden."
L14_1.m_Talk_DEU = L15_1
L15_1 = "À mon avis, ils ont utilisé tous les substituts qui se trouvaient ici comme matériau pour les répliques d'agent qliphoth."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "EP5_ACT5_STAGE4_START@165#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 165
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 208
L15_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L15_1.m_Pos = "L"
L16_1 = "생체 대사를 통해 조금씩 자가복제를 하는 대신, 육신을 구성하는 리플레이서 인자를 모조리 분해해서 단숨에 대량의 리플레이서 인자를 회수하는 거죠."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "生体代謝で少しずつ自己複製をする代わりに、肉体を構成する\nリプレイサーファクターをすべて分解して、一気に大量のリプレイサーファクターを回収するんです。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Instead of letting the Replacers slowly duplicate factors through metabolism, they chose to dismantle all the Replacer Factors comprising the Replacers' bodies to obtain a massive amount of them."
L15_1.m_Talk_ENG = L16_1
L16_1 = "比起透過活體代謝，一點點地進行自我複製，將構成肉身的克隆因子全部分解掉，就可以一口氣回收大量的克隆因子了。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "แทนที่จะปล่อยให้รีเพลสเซอร์ค่อยๆ สร้างแฟกเตอร์ผ่านการเผาผลาญ พวกเขาเลือกที่จะแยกชิ้นส่วนรีเพลสเซอร์แฟกเตอร์ทั้งหมดที่ประกอบขึ้นเป็นร่างกายของรีเพลสเซอร์ เพื่อเก็บรีเพลสเซอร์แฟกเตอร์จำนวนมาก"
L15_1.m_Talk_THA = L16_1
L16_1 = "Thay vì để Người Nhân Bản từ từ sao chép các nhân tố thông qua quá trình trao đổi chất, họ đã chọn tách rời tất cả Nhân Tố Nhân Bản tạo thành cơ thể của Người Nhân Bản để thu được một lượng lớn các nhân tố này."
L15_1.m_Talk_VTN = L16_1
L16_1 = "虽然可以通过活体代谢自我复制，但是分解构成肉身的克隆因子可以一次性回收大量的克隆因子。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Statt die Replacer langsam durch Verstoffwechselung neue Faktoren produzieren zu lassen, haben sie die Körper der Replacer zerlegt, um an möglichst viele Replacer-Faktoren zu gelangen."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Au lieu de les laisser dupliquer lentement leur agent par le biais de leur métabolisme, vous avez choisi d'assimiler l'ensemble de l'agent qu'on trouvait dans leur corps pour en obtenir une très grande quantité."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
