L18_1 = "EP5_ACT5_STAGE4_START@167#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 167
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 208
L17_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L17_1.m_Pos = "R"
L18_1 = "그러니까...... 자기 편까지 희생시켰다는 거야?"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "つまり……味方まで犠牲にしたってこと？"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Are you saying that they've sacrificed the lives of their own?"
L17_1.m_Talk_ENG = L18_1
L18_1 = "所以是說……他們連自己的部隊都犧牲了？"
L17_1.m_Talk_TWN = L18_1
L18_1 = "นายจะบอกว่าพวกเขาตั้งใจสละชีวิตตัวเองเหรอ?"
L17_1.m_Talk_THA = L18_1
L18_1 = "Bạn đang nói rằng họ đã hy sinh mạng sống của chính họ sao?"
L17_1.m_Talk_VTN = L18_1
L18_1 = "所以是说……他们在自己的部队里牺牲了？"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Willst du damit sagen, sie haben ihre eigenen Leute geopfert?"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Tu veux dire qu'ils ont sacrifié la vie des leurs ?"
L17_1.m_Talk_FRA = L18_1
