L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L18_1.m_Pos = "R"
L19_1 = "그...... 클리포트 인자인가 뭔가 하는 걸 만들려고?"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "その……クリフォト・ファクターとやらを作るために？"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Just to produce this Qliphoth thing?"
L18_1.m_Talk_ENG = L19_1
L19_1 = "……就為了製造逆卡巴拉因子或什麼的？"
L18_1.m_Talk_TWN = L19_1
L19_1 = "แต่เพื่อผลิตไอ้คลิฟอธอะไรเนี่ยนะ?"
L18_1.m_Talk_THA = L19_1
L19_1 = "Chỉ để sản xuất thứ Qliphoth này?"
L18_1.m_Talk_VTN = L19_1
L19_1 = "……为了制造神圣因子还是什么的？"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Nur um dieses Klippot-Zeug zu produzieren?"
L18_1.m_Talk_DEU = L19_1
L19_1 = "Juste pour produire ce machin qliphoth ?"
L18_1.m_Talk_FRA = L19_1
