L19_1.m_Crash = 25
L20_1 = "그럼...... 대체 몇 명이나 살아남는다는 거야?"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "じゃあ……いったい何人生き残れるわけ？"
L19_1.m_Talk_JPN = L20_1
L20_1 = "H-how many survivors can there be if this is what they have to go through?"
L19_1.m_Talk_ENG = L20_1
L20_1 = "那麼……到底會有多少人活著呢？"
L19_1.m_Talk_TWN = L20_1
L20_1 = "จะเหลือผู้รอดชีวิตกี่คนกัน หากทุกคนต้องทำแบบนี้?"
L19_1.m_Talk_THA = L20_1
L20_1 = "C-có thể có bao nhiêu người sống sót nếu đây là điều họ phải trải qua?"
L19_1.m_Talk_VTN = L20_1
L20_1 = "那么……到底还有多少人活着呢？"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Wie … wie viele bleiben angesichts dieser Zahlen denn überhaupt noch übrig?"
L19_1.m_Talk_DEU = L20_1
L20_1 = "C-Combien il peut y avoir de survivants si c'est ça la méthode à employer ?"
L19_1.m_Talk_FRA = L20_1
