L23_1 = "최종적으로는 전 세계 인구의 약 0.003% 정도겠지."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "最終的には、世界総人口のうち、約0.003％程度になるだろう。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "At the end, I would say about 0.003% of the current world population."
L22_1.m_Talk_ENG = L23_1
L23_1 = "最後大約會有全世界人口的0.003%吧。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "สุดท้ายแล้วผมคิดว่าจะเหลือประชากรโลกเพียง 0.003% เท่านั้น"
L22_1.m_Talk_THA = L23_1
L23_1 = "Cuối cùng, tôi đoán là khoảng 0,003% dân số thế giới hiện tại."
L22_1.m_Talk_VTN = L23_1
L23_1 = "最终大概是全世界人口的0.003%吧。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Ich würde sagen, unterm Strich sprechen wir von 0,003 % der Weltbevölkerung."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Au final, je dirais quelque chose comme 0,003 % de la population mondiale actuelle."
L22_1.m_Talk_FRA = L23_1
