L24_1 = "나머지 사람들은...... 어떻게 되는 건데?"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "残りの人は……どうなるの？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "And what happens to the rest?"
L23_1.m_Talk_ENG = L24_1
L24_1 = "剩下的人們會……怎麼樣呢？"
L23_1.m_Talk_TWN = L24_1
L24_1 = "แล้วจะเกิดอะไรขึ้นกับคนอื่นๆ ล่ะ?"
L23_1.m_Talk_THA = L24_1
L24_1 = "Và điều gì xảy ra với những người còn lại?"
L23_1.m_Talk_VTN = L24_1
L24_1 = "剩下的人们会……怎么样呢？"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Und der Rest?"
L23_1.m_Talk_DEU = L24_1
L24_1 = "Et que se passe-t-il pour tous les autres ?"
L23_1.m_Talk_FRA = L24_1
