L25_1.m_Pos = "C"
L26_1 = "안타깝지만...... 불가피한 희생이라고 생각한다."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "残念だが……やむを得ない犠牲だ。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "I'll just say plans like this are bound to cause collateral damage."
L25_1.m_Talk_ENG = L26_1
L26_1 = "很遺憾……他們會無可避免地被犧牲。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ผมแค่จะบอกว่าแผนการแบบนี้ต้องมีความเสียหายข้างเคียงบ้างอยู่แล้ว"
L25_1.m_Talk_THA = L26_1
L26_1 = "Tôi sẽ chỉ nói rằng những kế hoạch như thế này chắc chắn sẽ có mặt bất lợi khác."
L25_1.m_Talk_VTN = L26_1
L26_1 = "很可惜……我觉得是会牺牲。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Ich sage mal so: Pläne wie dieser verursachen nun mal Kollateralschäden."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Je dirais simplement qu'un plan de cette ampleur occasionne nécessairement des pertes collatérales."
L25_1.m_Talk_FRA = L26_1
