L30_1 = "EP5_ACT5_STAGE4_START@179#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 179
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 208
L29_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L29_1.m_Pos = "R"
L30_1 = "완전히 미쳤어. 너무 황당해서 화를 낼 생각도 안 들어."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "完全にイカれてるよ。あり得なさ過ぎて、怒る気にもなれない。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "This is absolute madness. I'm so shocked that I don't even feel angry."
L29_1.m_Talk_ENG = L30_1
L30_1 = "完全瘋了，瘋到我連氣都生不出來了。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "นี่มันบ้าชัดๆ ฉันตกใจจนไม่รู้สึกโกรธด้วยซ้ำ"
L29_1.m_Talk_THA = L30_1
L30_1 = "Điều này hoàn toàn điên rồ. Tôi sốc đến mức không thể cảm thấy tức giận."
L29_1.m_Talk_VTN = L30_1
L30_1 = "真是疯了。这也太荒唐了。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Das ist vollkommen irre. Ich bin so schockiert, dass ich noch nicht mal wütend bin."
L29_1.m_Talk_DEU = L30_1
L30_1 = "C'est de la folie. Je suis tellement abasourdie que je ne me sens même pas en colère."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "EP5_ACT5_STAGE4_START@180#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 180
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 208
L30_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L30_1.m_Pos = "R"
L31_1 = "선배, 저 헛소리를 더 듣고 있을 생각은 아니지?"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "先輩、あんなふざけたことこれ以上聞くつもりないよね？"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Shiyoon, you're not going to keep listening to that crap, are you?"
L30_1.m_Talk_ENG = L31_1
L31_1 = "前輩，你不會還想要聽這種垃圾話吧？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ชิยุน นายจะไม่ฟังเรื่องเหลวไหลนี่ต่อไปใช่ไหม?"
L30_1.m_Talk_THA = L31_1
L31_1 = "Shiyoon, bạn không định tiếp tục nghe những thứ tào lao đó nữa chứ?"
L30_1.m_Talk_VTN = L31_1
L31_1 = "前辈，你不会还想听到这种荒唐话吧？"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Shiyoon, du hörst dir doch diesen Mist nicht weiter an, oder?"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Charles, tu vas pas continuer à écouter ces foutaises, hein ?"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "EP5_ACT5_STAGE4_START@181#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 181
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 208
L31_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L31_1.m_Pos = "R"
L32_1 = "당장 박살내 버리자고."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "今すぐ倒しちゃおうよ。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Let's just smash everything up."
L31_1.m_Talk_ENG = L32_1
L32_1 = "馬上把這裡毀掉吧。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "มาทำลายที่นี่กันเถอะ"
L31_1.m_Talk_THA = L32_1
L32_1 = "Hãy nghiền nát mọi thứ."
L31_1.m_Talk_VTN = L32_1
L32_1 = "马上把这里毁掉吧。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Zerstören wir einfach alles."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Démolissons tout et finissons-en."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "EP5_ACT5_STAGE4_START@182#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 182
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 208
L32_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L32_1.m_Pos = "L"
L33_1 = "동감입니다만...... 그렇게 간단할 것 같진 않군요."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "同感ですが……そんなに簡単ではなさそうですね。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "I'd love to do that, but I'm afraid it won't be so easy."
L32_1.m_Talk_ENG = L33_1
L33_1 = "我有同感……但我想不會這麼簡單。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ผมก็อยากทำแบบนั้นนะ แต่เกรงว่าจะไม่ง่ายนัก"
L32_1.m_Talk_THA = L33_1
L33_1 = "Tôi rất muốn làm điều đó, nhưng tôi e rằng sẽ không dễ dàng như vậy."
L32_1.m_Talk_VTN = L33_1
L33_1 = "我理解你的感受……但这不是这么简单的事情。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Würde ich ja gern, aber ich fürchte, so einfach ist es nicht."
L32_1.m_Talk_DEU = L33_1
L33_1 = "J'aimerais bien, mais j'ai bien peur que ce ne soit pas si facile."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
