L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 208
L33_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L33_1.m_bWaitClick = false
L33_1.m_fWaitTime = 0
L33_1.m_bClear = true
L34_1 = {}
L35_1 = "EP5_ACT5_STAGE4_START@184#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 184
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 208
L34_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L34_1.m_Pos = "C"
L35_1 = "이해 받을 수 있을 거라 생각하진 않았지만...... 그래도 직접 들으니 씁쓸하군."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "理解してもらえるとは思わなかったが……それでも、直接言われたら寂しいな。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "I didn't think you'd understand, but it breaks my heart to actually hear it from you."
L34_1.m_Talk_ENG = L35_1
L35_1 = "雖然我不認為你們會理解……但直接聽到你們這麼說，還是讓人覺得很苦澀啊。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ผมไม่คิดว่าคุณจะเข้าใจ แต่พอได้ฟังจริงๆ แล้วเสียใจนะ"
L34_1.m_Talk_THA = L35_1
L35_1 = "Tôi không nghĩ rằng bạn sẽ hiểu, nhưng thật sự trái tim tôi tan nát khi chính tai nghe được điều đó từ bạn."
L34_1.m_Talk_VTN = L35_1
L35_1 = "虽然我不觉得这是可以被理解、接受的事情……但是听下来还是觉得很苦涩啊。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Ich habe nicht damit gerechnet, dass du das verstehst, aber es bricht mir das Herz, es zu hören."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Je ne pensais pas que vous comprendriez, mais ça me brise le cœur de vous entendre dire ça."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "EP5_ACT5_STAGE4_START@185#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 185
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 208
L35_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L35_1.m_Pos = "C"
L36_1 = "하지만 나도 물러설 생각은 없네."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "だが、私も引き下がるつもりはない。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "But I have no intention of backing off."
L35_1.m_Talk_ENG = L36_1
L36_1 = "但是我也沒有想要讓步的打算。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "แต่ผมไม่มีเจตนาที่จะถอย"
L35_1.m_Talk_THA = L36_1
L36_1 = "Nhưng tôi không có ý định lùi bước."
L35_1.m_Talk_VTN = L36_1
L36_1 = "但是我也没有想要让步。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Aber ich beabsichtige nicht, zurückzuweichen."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Je n'ai absolument pas l'intention de faire marche arrière."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "EP5_ACT5_STAGE4_START@186#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 186
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 208
L36_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L36_1.m_Pos = "C"
L37_1 = "리플레이서 간부들을 포함하여, 우리 모두 다 대의를 위한 죽음을 각오하고 있다."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "リプレイサー幹部を含め、我々全員は大義のための死を覚悟している。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Everyone in the organization, including my officers and myself, is prepared to die for our cause."
L36_1.m_Talk_ENG = L37_1
L37_1 = "包括克隆集團的幹部，我們全都有為大義而死的覺悟。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ทุกคนในองค์กรนี้ รวมถึงพวกเจ้าหน้าที่และตัวผมเอง เตรียมพร้อมที่จะตายเพื่อเป้าหมายของเรา"
L36_1.m_Talk_THA = L37_1
L37_1 = "Mọi người trong tổ chức, bao gồm cả các sĩ quan của tôi và bản thân tôi, đã sẵn sàng để chết vì lý tưởng của mình."
L36_1.m_Talk_VTN = L37_1
L37_1 = "包括克隆集团的头目们，我们都做好了为大义而牺牲的准备。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Alle im Syndikat, meine Offiziere und ich eingeschlossen, sind bereit, für unsere Sache zu sterben."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Tous dans l'organisation, mes officiers et moi-même y compris, sommes prêts à mourir pour notre cause."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "EP5_ACT5_STAGE4_START@187#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 187
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 208
L37_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L37_1.m_Pos = "C"
L38_1 = "퀸도, 나이트도, 폰도 이미 자신의 영혼이 파괴되는 것을 감수하면서까지 저 밖에서 수없이 파괴와 재생을 반복하고 있으니까."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "クイーンも、ナイトも、ポーンも、すでに自分の魂が壊れるのを自覚しながら、\n外で破壊と再生を繰り返している。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "You saw Queen, Knight, and Pawn. They are gladly letting their bodies be destroyed and reconstructed at the risk of their own souls."
L37_1.m_Talk_ENG = L38_1
L38_1 = "女皇也好，騎士也好，就連兵卒都接受了自己靈魂的毀壞，經歷了反覆不斷，無數次的破壞與再生。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "คุณเห็นควีน ไนท์ และพอว์นแล้ว พวกนั้นยินดีเสียสละให้ร่างกายของตัวเองถูกทำลายและสร้างใหม่ โดยที่ต้องเสี่ยงที่จะสูญเสียวิญญาณไปด้วย"
L37_1.m_Talk_THA = L38_1
L38_1 = "Bạn đã thấy Quân Hậu, Quân Xe và Quân Tốt. Họ vui mừng đánh đổi linh hồn để hiến cơ thể của chính mình để bị phá hủy và rồi được tái tạo."
L37_1.m_Talk_VTN = L38_1
L38_1 = "女皇、骑士、士兵都忍受了自己灵魂的坠落，在经历着一次又一次的死亡和重生。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Ihr habt Queen, Knight und Pawn gesehen. Sie lassen ihre Körper frohen Mutes zerlegen und neu zusammenbauen und riskieren ihre Seelen dafür."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Vous avez vu la reine, le cavalier et le pion. Ils laissent volontiers leur corps être détruit, encore et encore, au risque de perdre leur âme."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "EP5_ACT5_STAGE4_START@188#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 188
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 208
L38_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L38_1.m_Pos = "C"
L39_1 = "비숍, 최종 재배포까지 얼마나 남았지?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "ビショップ、最終再配布まであとどれくらいだ？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Bishop, how long do we have left until the final redistribution?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "主教，離最終的再發送還剩多少？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "บิช็อป เหลือเวลาอีกแค่ไหนสำหรับเวอร์ชันแจกจ่ายได้ขั้นสุดท้าย?"
L38_1.m_Talk_THA = L39_1
L39_1 = "Quân Tượng, còn bao lâu nữa cho đến lần phân phối lại cuối cùng?"
L38_1.m_Talk_VTN = L39_1
L39_1 = "主教，离最后的再分配？还剩多少？"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Bishop, wie lange noch bis zur finalen Umverteilung?"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Fou, combien de temps encore avant la redistribution finale ?"
L38_1.m_Talk_FRA = L39_1
