L42_1.m_Pos = "C"
L43_1 = "......퀸으로부터 진화 피드백이 고속으로 이루어지고 있다."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "……クイーンから、進化のフィードバックが高速で行われている。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "There's a massive amount of evolutionary feedback coming from Queen."
L42_1.m_Talk_ENG = L43_1
L43_1 = "……從女皇那裡接收的進化反饋正以高速進行著。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "มีพลังงานตอบสนองเชิงพัฒนาการมหาศาลจากควีน"
L42_1.m_Talk_THA = L43_1
L43_1 = "Có lượng lớn phản hồi tiến hóa từ Quân Hậu."
L42_1.m_Talk_VTN = L43_1
L43_1 = "……从女皇那里获得了高速的进化反馈。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Wir empfangen massives evolutionäres Feedback von Queen."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Il y a une énorme quantité de retours d'évolution en provenance de la reine."
L42_1.m_Talk_FRA = L43_1
