L43_1.m_Pos = "C"
L44_1 = "현재 리플레이서 레플리카 인자 최종 재배포 버전 조합 완료율은...... 92.1%"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "現在、レプリカ・クリフォト・ファクターによる、最終再配布版の組み合わせ完了率は……92.1％。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "The current completion rate of the final redistributable version of Replacer Replica Factor is... 92.1%"
L43_1.m_Talk_ENG = L44_1
L44_1 = "現在，克隆複製因子最終再發送版本的組合達成率……92.1%"
L43_1.m_Talk_TWN = L44_1
L44_1 = "อัตราการเสร็จสมบูรณ์ของเวอร์ชันแจกจ่ายได้ขั้นสุดท้ายของแฟกเตอร์รีเพลสเซอร์จำลองตอนนี้อยู่ที่... 92.1%"
L43_1.m_Talk_THA = L44_1
L44_1 = "Tỷ lệ hoàn thành hiện tại của phiên bản phân phối lại cuối cùng của Nhân Tố Bản Sao Nhân Bản là... 92,1%"
L43_1.m_Talk_VTN = L44_1
L44_1 = "现在克隆复制因子最终再分配版本组合完成率达到……92.1%"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Die aktuelle Fertigstellungsrate der finalen Verteilversion des nachgemachten Replacer-Faktors liegt bei … 92,1 %."
L43_1.m_Talk_DEU = L44_1
L44_1 = "La version finale de redistribution de la réplique d'agent substituteur est actuellement achevée à hauteur de... 92,1 %."
L43_1.m_Talk_FRA = L44_1
