L48_1 = "EP5_ACT5_STAGE4_START@197#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 197
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 208
L47_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L47_1.m_Pos = "L"
L48_1 = "아마도 스스로 퍼져나가면서 자가복제를 진행하는 클리포트 레플리카 인자를 말하는 걸 겁니다."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "たぶん、自ら広がって自己複製を行うレプリカ・クリフォト・ファクターのことだと思います。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "I bet it means the Qliphoth Replica Factor that's capable of spreading and duplicating itself."
L47_1.m_Talk_ENG = L48_1
L48_1 = "大概是在說一邊自我散播，一邊進行自我複製的逆卡巴拉複製因子吧。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ผมว่ามันคงหมายถึงคลิฟอธแฟกเตอร์จำลองที่สามารถกระจายตัวและสร้างตัวเองใหม่ได้น่ะ"
L47_1.m_Talk_THA = L48_1
L48_1 = "Tôi cá rằng nó có nghĩa là Nhân Tố Nhân Bản Qliphoth có khả năng tự lan truyền và nhân bản."
L47_1.m_Talk_VTN = L48_1
L48_1 = "大概是说自己散播出去进行自我复制的神圣复制因子吧。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Das ist dann wohl der nachgemachte Klippot-Faktor, der sich selbst vermehren und verbreiten kann."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Je parie qu'il s'agit de la réplique d'agent qliphoth capable de se répandre et de se dupliquer toute seule."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "EP5_ACT5_STAGE4_START@198#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 198
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 208
L48_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L48_1.m_Pos = "L"
L49_1 = "이미 리플레이서 인자에 감염된 사람이 전 세계에 퍼져 있는 이상, 한 번 배포되게 되면 설사 이들을 쓰러트린다고 해도 연쇄반응을 막을 수 없을 겁니다."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "すでにリプレイサーファクターに感染した人間が世界中にいる以上、\n一度広まってしまったら、たとえこの者たちを倒したとしても連鎖反応は防げないでしょうね。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "People infected by the Replacer Factors are spread all over the world. Once this gets distributed, there's going to be a devastating aftermath even if we manage to defeat them."
L48_1.m_Talk_ENG = L49_1
L49_1 = "被克隆因子感染的人已經遍佈全世界的情況下，如果再被發送一次，就算我們打敗了他們，也無法阻止連鎖反應了。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "คนที่ติดเชื้อรีเพลสเซอร์แฟกเตอร์จะกระจายไปทั่วโลก เมื่อมันถูกแจกจ่ายออกไปแล้วจะส่งผลกระทบรุนแรงเป็นวงกว้าง ต่อให้เราเอาชนะพวกมันได้"
L48_1.m_Talk_THA = L49_1
L49_1 = "Những người bị lây nhiễm Nhân Tố Nhân Bản lan truyền trên khắp thế giới. Một khi chúng được phân phối, sẽ có hậu quả tàn khốc ngay cả khi chúng ta có thể đánh bại chúng."
L48_1.m_Talk_VTN = L49_1
L49_1 = "被克隆因子感染的人已经遍布全世界，再分发一次的话，就算我们打败了他们也无法阻止连锁反应了。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Dann würden sich mit Replacer-Faktor infizierte Menschen auf der ganzen Welt ausbreiten. Die Folgen wären katastrophal, selbst wenn wir sie noch besiegen könnten."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Les gens infectés par l'agent substituteur sont répandus aux quatre coins du monde. Une fois que cet agent sera lancé, les conséquences seront dévastatrices, même si nous parvenons à les éliminer."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
