L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 201
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 208
L1_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L1_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L1_1.m_Pos = "C"
L2_1 = "그 말대로다."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "そのとおりだ。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "The boy's right."
L1_1.m_Talk_ENG = L2_1
L2_1 = "說得沒錯。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "พ่อหนุ่มคนนี้พูดถูกนะ"
L1_1.m_Talk_THA = L2_1
L2_1 = "Chàng trai đó nói đúng."
L1_1.m_Talk_VTN = L2_1
L2_1 = "没错。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Der Junge hat recht."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Le garçon a raison."
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "EP5_ACT5_STAGE4_START@202#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 202
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 208
L2_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L2_1.m_Pos = "C"
L3_1 = "설명은 이 정도면 충분히 한 것 같군. 그러니 제안을 하나 하지."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "説明はこれくらいで十分だろう。では、一つ提案しよう。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "I've given you enough explanations, I guess. Now, I'm going to make an offer."
L2_1.m_Talk_ENG = L3_1
L3_1 = "看來我解釋到這個程度，已經夠充分了。那麼我有一個建議。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ผมอธิบายไปมากแล้วละ ตอนนี้ผมจะยื่นข้อเสนอให้คุณ"
L2_1.m_Talk_THA = L3_1
L3_1 = "Tôi đã giải thích hết cho bạn rồi, tôi đoán vậy. Còn bây giờ, tôi sẽ đưa ra một đề nghị."
L2_1.m_Talk_VTN = L3_1
L3_1 = "我就解释到这里了。我有一个建议。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Aber genug der Erklärungen. Ich werde euch jetzt ein Angebot machen."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Je pense que je vous ai fourni suffisamment d'explications. Maintenant, je vais vous faire une proposition."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "EP5_ACT5_STAGE4_START@203#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 203
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 208
L3_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L3_1.m_Pos = "C"
L4_1 = "그동안 보여 준 실력과 잠재력으로 추측하건대......"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "これまで披露してくれた実力や潜在能力からして……"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Considering what you've shown me and the latent abilities that you have within you..."
L3_1.m_Talk_ENG = L4_1
L4_1 = "根據這段時間以來，你們展現出的實力和可能性……"
L3_1.m_Talk_TWN = L4_1
L4_1 = "เมื่อดูจากสิ่งที่คุณแสดงให้ผมเห็นและความสามารถที่ซ่อนอยู่ในตัวคุณ..."
L3_1.m_Talk_THA = L4_1
L4_1 = "Xem xét những gì bạn đã cho tôi thấy và những khả năng tiềm ẩn mà bạn có bên trong..."
L3_1.m_Talk_VTN = L4_1
L4_1 = "我根据这段时间你们的实力和潜力预测了一下……"
L3_1.m_Talk_SCN = L4_1
L4_1 = "In Anbetracht dessen, was ihr mir gezeigt habt und was noch in euch schlummert …"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Étant donné ce que vous m'avez montré et les capacités latentes qui sommeillent en vous..."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "EP5_ACT5_STAGE4_START@204#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 204
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 208
L4_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L4_1.m_Pos = "C"
L5_1 = "자네들이라면 분명 <color=#ffd34c>살아남는 쪽</color>에 속할 수 있을 거라고 생각한다."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "君たちならきっと、<color=#ffd34c>生き残るほう</color>に入るだろう。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "I'm sure that you'll belong among the <color=#ffd34c>survivors</color>."
L4_1.m_Talk_ENG = L5_1
L5_1 = "我認為你們一定是屬於<color=#ffd34c>活下來的</color>那一邊。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ผมมั่นใจว่าคุณจะเป็นหนึ่งใน<color=#ffd34c>ผู้รอดชีวิต</color>"
L4_1.m_Talk_THA = L5_1
L5_1 = "Tôi chắc chắn rằng bạn sẽ thuộc về <color=#ffd34c>nhóm người sống sót</color>.\n"
L4_1.m_Talk_VTN = L5_1
L5_1 = "我觉得你们是可以活下来的<color=#ffd34c>那一种</color>。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "bin ich mir sicher, dass ihr zu den <color=#ffd34c>Überlebenden</color> gehören werdet."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Je suis certain que vous avez votre place parmi les <color=#ffd34c>survivants</color>."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "EP5_ACT5_STAGE4_START@205#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 205
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 208
L5_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L5_1.m_Pos = "C"
L6_1 = "그러니 이곳에서 무익하게 나와 싸우는 대신 클리포트 레플리카 인자를 이식 받고, 이후 이면세계로 이주할 인류를 도울 생각이 있는지 묻고 싶군."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "だから、ここで私と無益な戦いをする代わりに、レプリカ・クリフォト・ファクターの移植を受けて、\nいずれ裏世界へ移住する人類を助けるつもりはあるか確認したい。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "So I'd like to ask if you're willing to have the Qliphoth Replica Factors transplanted on you and help mankind migrate to the Counterside instead of fighting a meaningless battle against me here."
L5_1.m_Talk_ENG = L6_1
L6_1 = "所以比起在這裡進行沒有意義的戰鬥，不知道你們想不想接受逆卡巴拉複製因子的移植，幫助之後移居到異界的人們。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ผมจึงอยากรู้ว่าคุณจะยินยอมให้เราฝังคลิฟอธแฟกเตอร์จำลองไว้ในตัวคุณ แล้วช่วยให้มนุษยชาติอพยพมาที่เคาน์เตอร์ไซด์ แทนที่จะต้องต่อสู้กันอย่างไร้ความหมายที่ไหนไหม"
L5_1.m_Talk_THA = L6_1
L6_1 = "Vì vậy, tôi muốn hỏi liệu bạn có sẵn sàng cấy ghép Nhân Tố Nhân Bản Qliphoth vào bạn và giúp nhân loại di cư đến Counterside thay vì tham gia một trận chiến vô nghĩa để chống lại tôi ở đây không."
L5_1.m_Talk_VTN = L6_1
L6_1 = "所以比起在这里没有意义的战斗，不知道你们想不想接受神圣因子的移植，以后帮助移居到异界的人们。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Deshalb möchte ich euch fragen, ob ihr euch nachgemachte Klippot-Faktoren implantieren lassen und der Menschheit bei der Anpassung an die Counterside helfen wollt, statt hier einen sinnlosen Kampf gegen mich zu führen."
L5_1.m_Talk_DEU = L6_1
L6_1 = "J'aimerais vous demander si vous êtes prêts à recevoir la réplique de l'agent qliphoth et aider l'humanité à migrer vers le Contremonde au lieu me livrer une bataille insignifiante ici même."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
