L9_1 = "EP5_ACT5_STAGE4_START@208#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L8_1.m_CutScenProcessKey = 208
L8_1.m_CutScenID = 208
L8_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_Face = "UNIT_SERIOUS"
L8_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L8_1.m_Pos = "R"
L9_1 = 40
L8_1.m_Crash = L9_1
L9_1 = "헛소리! 그게 네 마음대로 될 것 같아?"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "ふざけるな！　あんたの思い通りになるとでも思った？"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Nonsense! That's never going to happen!"
L8_1.m_Talk_ENG = L9_1
L9_1 = "開什麼玩笑！你想怎樣就怎樣嗎？"
L8_1.m_Talk_TWN = L9_1
L9_1 = "เหลวไหล! ไม่มีทางเด็ดขาด!"
L8_1.m_Talk_THA = L9_1
L9_1 = "Vô lý! Điều đó sẽ không bao giờ xảy ra!"
L8_1.m_Talk_VTN = L9_1
L9_1 = "荒唐！你想什么就是什么吗？"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Blödsinn! Das wird nie passieren!"
L8_1.m_Talk_DEU = L9_1
L9_1 = "C'est absurde ! Ça n'arrivera jamais !"
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "EP5_ACT5_STAGE4_START@209#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 209
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 208
L9_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L9_1.m_Pos = "R"
L9_1.m_Crash = 20
L10_1 = "어차피 네놈의 그 웃기지도 않는 계획은 여기서 박살 날 테니까 승낙하고 말고 할 것도 없어!"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "あんたのそのふざけた計画は、どうせここで阻止するんだから、承諾も何もないよ！"
L9_1.m_Talk_JPN = L10_1
L10_1 = "This is where your preposterous plan ends, so I won't have to answer to that ridiculous question."
L9_1.m_Talk_ENG = L10_1
L10_1 = "反正你們那無聊的計畫就會在這裡結束，同不同意都無所謂！"
L9_1.m_Talk_TWN = L10_1
L10_1 = "แผนการบ้าๆ ของคุณต้องจบลงตรงนี้ ฉันจะได้ไม่ต้องตอบคำถามที่น่าหัวเราะแบบนั้น"
L9_1.m_Talk_THA = L10_1
L10_1 = "Đây là nơi kế hoạch phi lý của bạn sẽ kết thúc, vì vậy tôi sẽ không phải trả lời câu hỏi ngu ngốc đó."
L9_1.m_Talk_VTN = L10_1
L10_1 = "反正你们那荒唐的计划也会在这里终结，也无所谓同不同意了！"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Dein absurder Plan endet hier und jetzt. Ich weigere mich, auf diese lächerliche Frage zu antworten."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Votre plan grotesque se termine ici et maintenant, ça m'épargnera de devoir répondre à cette question ridicule."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "EP5_ACT5_STAGE4_START@210#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 210
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 208
L10_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L10_1.m_Pos = "L"
L11_1 = "유감이지만 저도 마찬가지입니다."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "残念ながら、僕も同じです。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "I'm sorry but I'll have to agree with her."
L10_1.m_Talk_ENG = L11_1
L11_1 = "很遺憾，我也一樣。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ขอโทษนะ แต่ผมก็เห็นด้วยกับเธอ"
L10_1.m_Talk_THA = L11_1
L11_1 = "Tôi xin lỗi nhưng tôi sẽ phải đồng ý với cô ấy."
L10_1.m_Talk_VTN = L11_1
L11_1 = "很遗憾，我也是一样的想法。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Da muss ich ihr leider zustimmen."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Désolé, mais je me dois d'être d'accord avec elle."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "EP5_ACT5_STAGE4_START@211#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 211
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 208
L11_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L11_1.m_Pos = "L"
L12_1 = "그런 짓을 했다간 스승님께 무슨 잔소리를 들을지 모르겠거든요."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "そんなことしたら、師匠にどんな説教を浴びせられるかわかりませんからね。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "I can't even begin to think what Master would say to me if I did something like that."
L11_1.m_Talk_ENG = L12_1
L12_1 = "我要是做出那種事情，真不知道師父會念些什麼呢。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ผมนึกไม่ออกด้วยซ้ำว่าอาจารย์จะว่ายังไง หากผมทำอะไรแบบนั้น"
L11_1.m_Talk_THA = L12_1
L12_1 = "Tôi thậm chí không thể bắt đầu nghĩ rằng Sếp sẽ nói gì với tôi nếu tôi làm điều gì đó như vậy."
L11_1.m_Talk_VTN = L12_1
L12_1 = "我要是做那种事情，还不知道老师会唠叨些什么呢。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Ich möchte gar nicht wissen, was die Meisterin sagen würde, wenn ich so etwas täte."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Je n'arrive même pas à imaginer ce que le maître me dirait si je faisais une chose pareille."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
