L14_1 = "EP5_ACT5_STAGE4_START@213#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 213
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 208
L13_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Face = "UNIT_DESPAIR"
L13_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L13_1.m_Pos = "C"
L14_1 = "그런가...... 그럼 협상은 결렬이로군."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "そうか……では、交渉決裂だな。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "I see... The deal's off then."
L13_1.m_Talk_ENG = L14_1
L14_1 = "這樣啊……那交涉失敗了呢。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "เข้าใจแล้ว... งั้นข้อเสนอก็เป็นโมฆะ"
L13_1.m_Talk_THA = L14_1
L14_1 = "Tôi hiểu rồi... Vậy thỏa thuận coi như bỏ."
L13_1.m_Talk_VTN = L14_1
L14_1 = "这样啊……那么我们算是协商失败了呢。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Ich verstehe … Dann ist das Angebot vom Tisch."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Je vois... Je retire mon offre dans ce cas."
L13_1.m_Talk_FRA = L14_1
