L15_1 = "그렇다면 나 역시 전력을 다해 자네들을 쓰러뜨리고 프로젝트 테라사이드를 완수할 수밖에."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "だったら、私も全力で君たちを倒し、プロジェクトテラサイドを完遂するしかない。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "I have no choice but to defeat you and complete Project Terraside."
L14_1.m_Talk_ENG = L15_1
L15_1 = "那麼我就只有全力擊敗你們，完成特拉賽德計畫了。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ผมไม่มีทางเลือกอื่นนอกจากจะเอาชนะพวกคุณและทำโปรเจ็กต์เทอร์ราไซด์ให้เสร็จ"
L14_1.m_Talk_THA = L15_1
L15_1 = "Tôi không có lựa chọn nào khác ngoài việc đánh bại bạn và hoàn thành Terraside Dự Án."
L14_1.m_Talk_VTN = L15_1
L15_1 = "那么我就只有全力击败你们，然后完成特拉赛德项目了。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Ich habe keine andere Wahl, als euch zu besiegen und das Terraside-Projekt ohne euch zu beenden."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Je n'ai pas d'autre choix que de vous éliminer et de terminer le projet Terremonde."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
