L16_1 = "<color=#ffd34c>不滅体コア、サブプロセスに再割り当て</color>"
L15_1.m_Talk_JPN = L16_1
L16_1 = "<color=#ffd34c>Immortal System Core sub-process reallocated.</color>"
L15_1.m_Talk_ENG = L16_1
L16_1 = "<color=#ffd34c>不滅者核心子程序再發送</color>"
L15_1.m_Talk_TWN = L16_1
