L15_1.m_Talk_SCN = L16_1
L16_1 = "<color=#ffd34c>Unterprozess des Kerns der Unsterblichkeitsmatrix umgeschichtet.</color>"
L15_1.m_Talk_DEU = L16_1
L16_1 = "<color=#ffd34c>Réaffectation des sous-programmes du noyau du système immortel.</color>"
