L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "<color=#ffd34c>リプレイサーエリートおよび重火力支援型の崩壊剤、緊急再生シーケンスを稼動</color>"
L16_1.m_Talk_JPN = L17_1
L17_1 = "<color=#ffd34c>Starting emergency regeneration of Replacer Elites and heavily armed supporter type collapsers.</color>"
L16_1.m_Talk_ENG = L17_1
L17_1 = "<color=#ffd34c>克隆集團精英與重火力支援型崩潰體緊急再生程序啟動</color>"
L16_1.m_Talk_TWN = L17_1
L17_1 = "<color=#ffd34c>เริ่มการสร้างรีเพลสเซอร์ระดับสูงและคอแลปเซอร์ประเภทซัพพอร์ตติดอาวุธหนักแบบฉุกเฉิน</color>"
L16_1.m_Talk_THA = L17_1
L17_1 = "<color=#ffd34c>Bắt đầu quá trình tái tạo khẩn cấp của Người Nhân Bản Ưu Tú và những kẻ phá hủy loại hỗ trợ được vũ trang hạng nặng.</color>"
L16_1.m_Talk_VTN = L17_1
L17_1 = "<color=#ffd34c>启动克隆集团精英和重火力支援型崩溃体紧急再生序列</color>"
L16_1.m_Talk_SCN = L17_1
L17_1 = "<color=#ffd34c>Beginne Notfallregeneration der Replacer-Eliten und schwer bewaffneter Zerborstener zur Unterstützung.</color>"
L16_1.m_Talk_DEU = L17_1
L17_1 = "<color=#ffd34c>Régénération d'urgence des élites substituts et des anomalies de type soutien armé lourd enclenchée.</color>"
L16_1.m_Talk_FRA = L17_1
