L20_1 = "크르륵...... 적은...... 적은 어디에 있지?"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "グルル……敵は……敵はどこだ？"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Grrrrr... Enemies... Where are my enemies?"
L19_1.m_Talk_ENG = L20_1
L20_1 = "唔啊啊……敵人……敵人在哪裡？"
L19_1.m_Talk_TWN = L20_1
L20_1 = "กรรร... ศัตรู... ศัตรูอยู่ไหน?"
L19_1.m_Talk_THA = L20_1
L20_1 = "Grrrrr... Kẻ thù... Kẻ thù của tôi ở đâu?"
L19_1.m_Talk_VTN = L20_1
L20_1 = "吭呃呃……敌人……敌人在哪里？"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Grrrrr … Feinde … Wo sind meine Feinde?"
L19_1.m_Talk_DEU = L20_1
L20_1 = "Grrr... Ennemis... Où sont mes ennemis ?"
L19_1.m_Talk_FRA = L20_1
