L23_1.m_Face = "UNIT_SURPRISE"
L23_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L23_1.m_Pos = "R"
L23_1.m_Crash = 20
L24_1 = "뭐, 뭐야 이것들은? 갑자기 어디서 나타난 거지?"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "な、なに、こいつら？　どこから現れたの？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "W-what are these? Where did they come from?"
L23_1.m_Talk_ENG = L24_1
L24_1 = "這、這些傢伙是怎麼回事？突然從那裡冒出來的啊？"
L23_1.m_Talk_TWN = L24_1
L24_1 = "นะ-นี่มันตัวอะไร? พวกมันมาจากไหน?"
L23_1.m_Talk_THA = L24_1
L24_1 = "C-cái gì đây? Chúng đến từ đâu vậy?"
L23_1.m_Talk_VTN = L24_1
L24_1 = "什么啊，这些是什么？从哪里突然出来的啊？"
L23_1.m_Talk_SCN = L24_1
L24_1 = "W-Was sind denn das für welche? Wo kommen die her?"
L23_1.m_Talk_DEU = L24_1
L24_1 = "C-C'est quoi ces trucs ? Ils sortent d'où ?"
L23_1.m_Talk_FRA = L24_1
