L25_1 = "EP5_ACT5_STAGE4_START@224#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 224
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 208
L24_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L24_1.m_Pos = "R"
L25_1 = "여기에 있던 리플레이서 병력들은 모두 재료로 사용된 거 아니었어?"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "ここにいたリプレイサー兵は、全員材料になったんじゃなかった？"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Weren't all the Replacer forces here already consumed as material?"
L24_1.m_Talk_ENG = L25_1
L25_1 = "這裡的克隆集團兵力不是全都被當成材料了嗎？"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ไม่ใช่ว่ากองกำลังรีเพลสเซอร์ทั้งหมดที่นี่ถูกใช้เป็นวัสดุไปหมดแล้วเหรอ?"
L24_1.m_Talk_THA = L25_1
L25_1 = "Chẳng phải tất cả lực lượng Người Nhân Bản ở đây đã được dùng làm nguyên liệu rồi sao?"
L24_1.m_Talk_VTN = L25_1
L25_1 = "这里的克隆集团兵力不是都被用作材料了吗？"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Ich dachte, alle Replacer hier wären als Material verheizt worden?"
L24_1.m_Talk_DEU = L25_1
L25_1 = "T'avais pas dit que toutes les forces substituts du secteur avaient été consumées ?"
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "EP5_ACT5_STAGE4_START@225#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 225
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 208
L25_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L25_1.m_Pos = "L"
L26_1 = "아마도 우릴 상대하기 위해 불멸체 코어로 임시 재생체를 만들어 낸 모양이군요."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "おそらく僕たちの相手をさせるために、不滅体コアで仮の再生体を作りだしたようです。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "It seems they've temporarily produced regenerated Replacers with the Immortal System Core."
L25_1.m_Talk_ENG = L26_1
L26_1 = "大概是為了對付我們，用不滅者核心製造出的臨時再生體吧。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ดูเหมือนว่าพวกมันจะสร้างรีเพลสเซอร์ขึ้นมาใหม่แบบชั่วคราวด้วยแกนระบบอิมมอร์ทอลนะ"
L25_1.m_Talk_THA = L26_1
L26_1 = "Có vẻ như họ đã tạm thời sản xuất Người Nhân Bản tái tạo bằng Lõi Hệ Thống Bất Diệt."
L25_1.m_Talk_VTN = L26_1
L26_1 = "大概是为了对付我们用不灭者核心制造出的临时再生体吧。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Es scheint, dass sie mit dem Kern der Unsterblichkeitsmatrix kurzfristig regenerierte Replacer geschaffen haben."
L25_1.m_Talk_DEU = L26_1
L26_1 = "On dirait qu'ils ont temporairement produit des substituts régénérés avec le noyau du système immortel."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "EP5_ACT5_STAGE4_START@226#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 226
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 208
L26_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L26_1.m_Pos = "L"
L27_1 = "조심하세요, 미나 양."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "ご用心を、ミナさん。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Be careful, Mina."
L26_1.m_Talk_ENG = L27_1
L27_1 = "小心，米娜小姐。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ระวังตัวด้วยนะ มีนา"
L26_1.m_Talk_THA = L27_1
L27_1 = "Hãy cẩn thận, Mina."
L26_1.m_Talk_VTN = L27_1
L27_1 = "小心，米娜小姐。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Sei vorsichtig, Mina."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Fais attention, Mina."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "EP5_ACT5_STAGE4_START@227#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 227
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 208
L27_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L27_1.m_Pos = "L"
L28_1 = "저것들은 기존 리플레이서의 전투경험을 집약해서 만든 방어 병력일 겁니다."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "あれらは、既存のリプレイサーの戦闘経験を集約して作りだした防御部隊でしょう。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "We'll be dealing with defensive forces created with all the combat memories the Syndicate has accumulated."
L27_1.m_Talk_ENG = L28_1
L28_1 = "他們是集合了克隆集團既存的戰鬥經驗，被創造出來的防禦兵力。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "เราจะต้องรับมือกับกองกำลังป้องกันที่สร้างขึ้นมาพร้อมกับความทรงจำในการต่อสู้ที่ซินดิเคตสั่งสมมา"
L27_1.m_Talk_THA = L28_1
L28_1 = "Chúng ta sẽ đối phó với các lực lượng phòng thủ được tạo ra bằng tất cả những ký ức chiến đấu mà Nghiệp Đoàn đã tích lũy được."
L27_1.m_Talk_VTN = L28_1
L28_1 = "他们是集合了克隆集团已有的战斗经验而被创造出来的防御兵力。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Wir haben es mit Verteidigern zu tun, die über die gesammelte Kampferfahrung des Syndikats verfügen."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Nous faisons face à des troupes défensives créées avec toutes les expériences de combat que le Syndicat a accumulées."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "EP5_ACT5_STAGE4_START@228#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 228
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 208
L28_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L28_1.m_Pos = "L"
L29_1 = "어쩌면 거의 간부급에 준하는 전투력을 가지고 있을 수도 있어요."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "ひょっとすると、幹部級に順ずる戦闘力を持っているかもしれません。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "They could be as powerful as officers."
L28_1.m_Talk_ENG = L29_1
L29_1 = "他們大概有著與幹部不相上下的戰鬥力。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "พวกมันอาจทรงพลังพอๆ กับพวกเจ้าหน้าที่เลย"
L28_1.m_Talk_THA = L29_1
L29_1 = "Chúng có thể mạnh mẽ như các sĩ quan."
L28_1.m_Talk_VTN = L29_1
L29_1 = "他们的战斗力可能不亚于头目们。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Sie könnten so stark sein wie Offiziere."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Ils pourraient être aussi puissants que des officiers."
L28_1.m_Talk_FRA = L29_1
