L31_1 = "EP5_ACT5_STAGE4_START@230#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 230
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 208
L30_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L30_1.m_Pos = "C"
L31_1 = "이래 봬도 자네들이 태어나기도 전부터 침식체들과 싸워 온 몸이지."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "こう見えても、君たちが生まれる前から侵食体と戦ってきたんだ。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "I've fought C.O.s since before you were even born."
L30_1.m_Talk_ENG = L31_1
L31_1 = "別看我這樣，我可是在你們出生前，和侵蝕體一路戰鬥過來的人。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ผมเคยสู้กับวัตถุคอร์รัปต์มาตั้งแต่ก่อนพวกคุณเกิด"
L30_1.m_Talk_THA = L31_1
L31_1 = "Tôi đã chiến đấu với V.T.B.A.M từ trước khi bạn được sinh ra."
L30_1.m_Talk_VTN = L31_1
L31_1 = "这么一看，你们俩是天生就和侵蚀体战斗过的啊。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Ich habe schon gegen C. O.s gekämpft, als ihr noch nicht geboren wart."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Je combattais des O.C. bien avant votre naissance."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "EP5_ACT5_STAGE4_START@231#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 231
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 208
L31_1.m_CutScenStrID = "EP5_ACT5_STAGE4_START"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_SERIOUS"
L31_1.m_CharStrID = "KING_REPLACER_NULL_NULL"
L31_1.m_Pos = "C"
L32_1 = "그리 호락호락하게 당해주진 않을 테니까...... 각오하도록."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "簡単にやられはしない……覚悟しろ。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "You shouldn't expect that I'd go down so easily. Brace yourselves."
L31_1.m_Talk_ENG = L32_1
L32_1 = "我是不會這麼輕易就被打敗的……做好覺悟吧！"
L31_1.m_Talk_TWN = L32_1
L32_1 = "คุณไม่ควรจะคิดว่าผมจะแพ้ง่ายๆ นะ เตรียมตัวให้ดีล่ะ"
L31_1.m_Talk_THA = L32_1
L32_1 = "Bạn không nên nghĩ rằng tôi sẽ dễ dàng bị hạ gục như vậy. Cố lên."
L31_1.m_Talk_VTN = L32_1
L32_1 = "我们可没有那么好对付……做好觉悟吧！"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Glaubt nicht, dass ich so schnell zu Boden gehe. Wappnet euch."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Ne vous attendez pas à ce que je me rende facilement. Préparez-vous."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
